/// Completion state for serve-safe lossless MTP12 generation.
///
/// Both variants retain the complete native generation receipt accumulated up
/// to the round boundary. Cancellation is therefore distinct from an inference
/// error without discarding the target-verification, timing, or resident-model
/// evidence that was already produced for the request.
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, serde::Serialize)]
pub enum Gemma4Mtp12MetalGenerationOutcome {
    Complete(Gemma4Mtp12MetalGeneration),
    Cancelled(Gemma4Mtp12MetalGeneration),
}

/// Incremental text release for target-verified token ids.
///
/// Gemma's SPM byte-fallback tokens may end a verifier round partway through a
/// UTF-8 scalar. `Tokenizer::decode` intentionally returns the valid prefix and
/// withholds that incomplete suffix. Keep the smallest token suffix responsible
/// for the withheld bytes, so a later verified round can complete the scalar;
/// clearing the whole batch here would silently lose those bytes. This state is
/// deliberately independent of verifier scheduling so it can also cover a
/// one-token budget tail.
#[cfg(any(target_os = "macos", test))]
#[derive(Debug, Default)]
struct Gemma4Mtp12StableTextStream {
    pending_token_ids: Vec<u32>,
    emitted_text: String,
}

#[cfg(any(target_os = "macos", test))]
impl Gemma4Mtp12StableTextStream {
    fn push_verified<F, D>(
        &mut self,
        verified_token_ids: &[u32],
        mut decode: D,
        on_delta: &mut F,
    ) -> Result<()>
    where
        F: FnMut(&str),
        D: FnMut(&[u32]) -> Result<String>,
    {
        for &token_id in verified_token_ids {
            self.pending_token_ids.push(token_id);
            let valid_text = decode(&self.pending_token_ids)?;
            if valid_text.is_empty() {
                continue;
            }

            // Select the shortest prefix which accounts for every currently
            // decodable character and leaves only an undecodable suffix. For
            // `[ASCII, UTF8_LEAD]`, this emits ASCII while retaining the lead;
            // once all continuation bytes arrive, the completed scalar itself
            // becomes that shortest prefix and is emitted exactly once.
            let mut consumed = None;
            for prefix_len in 1..=self.pending_token_ids.len() {
                if decode(&self.pending_token_ids[..prefix_len])? == valid_text
                    && decode(&self.pending_token_ids[prefix_len..])?.is_empty()
                {
                    consumed = Some(prefix_len);
                    break;
                }
            }
            let consumed = consumed.ok_or_else(|| {
                BackendError::RuntimeShapeMismatch(
                    "MTP stable text decoder could not isolate its valid token prefix".into(),
                )
            })?;
            on_delta(&valid_text);
            self.emitted_text.push_str(&valid_text);
            self.pending_token_ids.drain(..consumed);
        }
        Ok(())
    }
}

#[cfg(test)]
mod gemma4_mtp12_stable_text_stream_tests {
    use super::Gemma4Mtp12StableTextStream;

    fn decode_byte_fallback_prefix(token_ids: &[u32]) -> crate::Result<String> {
        let bytes: Vec<u8> = token_ids.iter().map(|id| *id as u8).collect();
        Ok(match std::str::from_utf8(&bytes) {
            Ok(text) => text.to_owned(),
            Err(error) => std::str::from_utf8(&bytes[..error.valid_up_to()])
                .unwrap_or("")
                .to_owned(),
        })
    }

    #[test]
    fn verified_byte_fallback_waits_for_complete_utf8_without_losing_valid_prefix() {
        let mut stream = Gemma4Mtp12StableTextStream::default();
        let mut deltas = Vec::<String>::new();
        {
            let mut capture = |delta: &str| deltas.push(delta.to_owned());
            stream
                .push_verified(
                    &[u32::from(b'A'), 0xf0],
                    decode_byte_fallback_prefix,
                    &mut capture,
                )
                .unwrap();
        }
        assert_eq!(deltas, ["A"]);
        assert_eq!(stream.pending_token_ids, [0xf0]);

        {
            let mut capture = |delta: &str| deltas.push(delta.to_owned());
            stream
                .push_verified(&[0x9f, 0x98], decode_byte_fallback_prefix, &mut capture)
                .unwrap();
        }
        assert_eq!(deltas, ["A"]);
        assert_eq!(stream.pending_token_ids, [0xf0, 0x9f, 0x98]);

        {
            let mut capture = |delta: &str| deltas.push(delta.to_owned());
            stream
                .push_verified(
                    &[0x80, u32::from(b'!')],
                    decode_byte_fallback_prefix,
                    &mut capture,
                )
                .unwrap();
        }
        assert_eq!(deltas, ["A", "😀", "!"]);
        assert!(stream.pending_token_ids.is_empty());
        assert_eq!(stream.emitted_text, "A😀!");
    }
}

#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Gemma4Mtp12AcceptanceDecision {
    accepted_drafts: usize,
    committed_input_rows: usize,
    mismatch_draft_index: Option<usize>,
    stop_token: Option<u32>,
    next_anchor_token: Option<u32>,
}

#[cfg(target_os = "macos")]
fn gemma4_mtp12_tail_verify_width(
    configured: usize,
    remaining_including_anchor: usize,
) -> Option<usize> {
    // Equivalent to `width <= remaining_after_anchor + 1`: this caller's
    // budget includes the already-predicted anchor as candidate row zero.
    [16usize, 8, 4, 2]
        .into_iter()
        .find(|&width| width <= configured && width <= remaining_including_anchor)
}

#[cfg(target_os = "macos")]
fn gemma4_mtp12_materialize_candidate_rows(
    plan: Gemma4Mtp12WidthRoundPlan,
    anchor_token: u32,
    drafts: &[u32],
) -> Option<(Vec<u32>, Vec<u32>)> {
    if drafts.len().checked_add(1)? != plan.logical_verify_width
        || plan.physical_verify_width < plan.logical_verify_width
        || plan.padding_rows != plan.physical_verify_width - plan.logical_verify_width
    {
        return None;
    }
    let mut candidates = Vec::with_capacity(plan.physical_verify_width);
    candidates.push(anchor_token);
    candidates.extend_from_slice(drafts);
    let padding_candidate_ids = vec![anchor_token; plan.padding_rows];
    candidates.extend_from_slice(&padding_candidate_ids);
    Some((candidates, padding_candidate_ids))
}

#[cfg(target_os = "macos")]
fn gemma4_mtp12_acceptance_decision(
    drafts: &[u32],
    target_greedy_ids: &[u32],
    stop_ids: &[u32],
) -> Option<Gemma4Mtp12AcceptanceDecision> {
    if target_greedy_ids.len() != drafts.len().checked_add(1)? {
        return None;
    }
    for (index, (&draft, &target)) in drafts.iter().zip(target_greedy_ids).enumerate() {
        if draft != target {
            let stop_token = stop_ids.contains(&target).then_some(target);
            return Some(Gemma4Mtp12AcceptanceDecision {
                accepted_drafts: index,
                committed_input_rows: 1 + index,
                mismatch_draft_index: Some(index),
                stop_token,
                next_anchor_token: stop_token.is_none().then_some(target),
            });
        }
        // A target-agreed stop is an output boundary, not another input row:
        // commit the anchor and preceding drafts but exclude this stop row.
        if stop_ids.contains(&draft) {
            return Some(Gemma4Mtp12AcceptanceDecision {
                accepted_drafts: index,
                committed_input_rows: 1 + index,
                mismatch_draft_index: None,
                stop_token: Some(draft),
                next_anchor_token: None,
            });
        }
    }
    let bonus = target_greedy_ids[drafts.len()];
    let stop_token = stop_ids.contains(&bonus).then_some(bonus);
    Some(Gemma4Mtp12AcceptanceDecision {
        accepted_drafts: drafts.len(),
        committed_input_rows: 1 + drafts.len(),
        mismatch_draft_index: None,
        stop_token,
        next_anchor_token: stop_token.is_none().then_some(bonus),
    })
}

#[cfg(all(test, target_os = "macos"))]
mod gemma4_mtp12_metal_generation_tests {
    use super::{
        gemma4_mtp12_acceptance_decision, gemma4_mtp12_materialize_candidate_rows,
        gemma4_mtp12_tail_verify_width, gemma4_mtp12_w16_oneshot_w8_pad16_policy,
        gemma4_mtp12_w16_warmup8_policy, Gemma4Mtp12AcceptanceDecision, Gemma4Mtp12MetalStats,
        Gemma4Mtp12WidthScheduleState, Gemma4Mtp12WidthScheduleTransition,
        Gemma4Mtp12WidthScheduler,
    };

    #[test]
    fn adaptive_w16_gate_is_default_off_and_fails_closed() {
        assert_eq!(gemma4_mtp12_w16_warmup8_policy(None), Ok(false));
        assert_eq!(gemma4_mtp12_w16_warmup8_policy(Some("0")), Ok(false));
        assert_eq!(gemma4_mtp12_w16_warmup8_policy(Some(" 1 ")), Ok(true));
        for invalid in ["", "true", "on", "2", "01", "disabled"] {
            let error = gemma4_mtp12_w16_warmup8_policy(Some(invalid))
                .expect_err("non-0/1 adaptive-width values must fail closed");
            assert!(error.contains("must be exactly 0 or 1"), "{error}");
        }
    }

    #[test]
    fn one_shot_padded_gate_is_default_off_and_fails_closed() {
        assert_eq!(gemma4_mtp12_w16_oneshot_w8_pad16_policy(None), Ok(false));
        assert_eq!(
            gemma4_mtp12_w16_oneshot_w8_pad16_policy(Some("0")),
            Ok(false)
        );
        assert_eq!(
            gemma4_mtp12_w16_oneshot_w8_pad16_policy(Some(" 1 ")),
            Ok(true)
        );
        for invalid in ["", "true", "on", "2", "01", "disabled"] {
            let error = gemma4_mtp12_w16_oneshot_w8_pad16_policy(Some(invalid))
                .expect_err("non-0/1 one-shot values must fail closed");
            assert!(error.contains("must be exactly 0 or 1"), "{error}");
        }
    }

    #[test]
    fn one_shot_w8_then_w16_pins_logical10_physical16_remaining11_tail() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new_one_shot_w8_padded_w16(16)
            .expect("one-shot configured W16");
        let mut generated = 0usize;
        let mut widths = Vec::new();

        let bootstrap = scheduler.plan_round(96).expect("one-shot W8 bootstrap");
        assert_eq!(bootstrap.logical_verify_width, 8);
        assert_eq!(bootstrap.physical_verify_width, 8);
        widths.push((8, 8));
        generated += 5; // Measured mismatch depth four: anchor + four drafts.
        let (state, transition) = scheduler
            .finish_round(bootstrap, 4, false)
            .expect("partial bootstrap still advances exactly once");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Wide16);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::OneShotBootstrapCompleteToW16
        );

        for _ in 0..5 {
            let wide = scheduler
                .plan_round(96 - generated)
                .expect("five measured full W16 rounds");
            assert_eq!(wide.logical_verify_width, 16);
            assert_eq!(wide.physical_verify_width, 16);
            widths.push((16, 16));
            generated += 16;
            scheduler.finish_round(wide, 15, false).expect("full W16");
        }
        assert_eq!(generated, 85);
        assert_eq!(96 - generated, 11, "remaining_including_anchor");

        let tail = scheduler.plan_round(11).expect("padded W16 tail");
        assert_eq!(tail.scheduled_verify_width, 16);
        assert_eq!(tail.logical_verify_width, 10);
        assert_eq!(tail.physical_verify_width, 16);
        assert_eq!(tail.padding_rows, 6);
        widths.push((10, 16));
        let drafts = (200u32..209).collect::<Vec<_>>();
        let (candidates, padding) = gemma4_mtp12_materialize_candidate_rows(tail, 42, &drafts)
            .expect("logical W10 padded to physical W16");
        let mut expected_logical = vec![42];
        expected_logical.extend_from_slice(&drafts);
        assert_eq!(&candidates[..10], expected_logical.as_slice());
        assert_eq!(padding, vec![42; 6]);
        assert_eq!(&candidates[10..], padding.as_slice());
        let (state, transition) = scheduler
            .finish_round(tail, 9, false)
            .expect("full logical W10 acceptance");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Wide16);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::BudgetTailHold
        );
        generated += 10;
        assert_eq!(generated, 95);
        assert!(scheduler.plan_round(1).is_none());
        generated += 1; // Final already-predicted target anchor, no target pass.
        assert_eq!(generated, 96);
        assert_eq!(
            widths,
            vec![
                (8, 8),
                (16, 16),
                (16, 16),
                (16, 16),
                (16, 16),
                (16, 16),
                (10, 16)
            ]
        );
    }

    #[test]
    fn one_shot_wide_partial_acceptance_holds_w16() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new_one_shot_w8_padded_w16(16)
            .expect("one-shot configured W16");
        let bootstrap = scheduler.plan_round(96).expect("bootstrap");
        scheduler
            .finish_round(bootstrap, 4, false)
            .expect("advance after partial bootstrap");
        let wide = scheduler.plan_round(91).expect("W16 after bootstrap");
        let (state, transition) = scheduler
            .finish_round(wide, 4, false)
            .expect("partial W16 holds one-shot policy");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Wide16);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::Wide16PartialHold
        );
        assert_eq!(
            scheduler
                .plan_round(86)
                .expect("still W16")
                .physical_verify_width,
            16
        );
    }

    #[test]
    fn adaptive_w16_measured_acceptance_shape_uses_8_8_then_wide_and_tail() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new(16, true);
        let mut generated = 0usize;
        let mut widths = Vec::new();
        let mut transitions = Vec::new();
        while generated < 96 {
            let Some(plan) = scheduler.plan_round(96 - generated) else {
                // The already-authoritative anchor satisfies the final W1 tail.
                generated += 1;
                break;
            };
            let accepted = if widths.is_empty() {
                4
            } else {
                plan.logical_verify_width - 1
            };
            widths.push(plan.physical_verify_width);
            generated += 1 + accepted;
            let (_, transition) = scheduler
                .finish_round(plan, accepted, false)
                .expect("valid measured acceptance shape");
            transitions.push(transition);
        }

        assert_eq!(generated, 96);
        assert_eq!(widths, vec![8, 8, 16, 16, 16, 16, 16, 2]);
        assert_eq!(
            transitions,
            vec![
                Gemma4Mtp12WidthScheduleTransition::WarmupPartialHold,
                Gemma4Mtp12WidthScheduleTransition::WarmupFullEscalateToW16,
                Gemma4Mtp12WidthScheduleTransition::Wide16FullHold,
                Gemma4Mtp12WidthScheduleTransition::Wide16FullHold,
                Gemma4Mtp12WidthScheduleTransition::Wide16FullHold,
                Gemma4Mtp12WidthScheduleTransition::Wide16FullHold,
                Gemma4Mtp12WidthScheduleTransition::Wide16FullHold,
                Gemma4Mtp12WidthScheduleTransition::BudgetTailHold,
            ]
        );
    }

    #[test]
    fn generic_warmup_hook_admits_w4_without_changing_the_public_w8_gate() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new_with_warmup_width(16, Some(4))
            .expect("source-only W4 qualification hook");
        let mut generated = 0usize;
        let mut widths = Vec::new();
        while generated < 96 {
            let plan = scheduler
                .plan_round(96 - generated)
                .expect("96-token full-acceptance shape has no W1 tail");
            widths.push(plan.physical_verify_width);
            let accepted = plan.logical_verify_width - 1;
            generated += plan.logical_verify_width;
            scheduler
                .finish_round(plan, accepted, false)
                .expect("full W4/W16/tail round");
        }
        assert_eq!(widths, vec![4, 16, 16, 16, 16, 16, 8, 4]);
        assert_eq!(generated, 96);
        assert!(Gemma4Mtp12WidthScheduler::new_with_warmup_width(16, Some(2)).is_none());
        assert!(Gemma4Mtp12WidthScheduler::new_with_warmup_width(16, Some(16)).is_none());
        assert!(Gemma4Mtp12WidthScheduler::new_with_warmup_width(8, Some(4)).is_none());
    }

    #[test]
    fn partial_w16_falls_back_and_must_requalify_through_full_w8() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new(16, true);

        let warmup = scheduler.plan_round(96).expect("initial W8");
        assert_eq!(warmup.physical_verify_width, 8);
        let (state, transition) = scheduler.finish_round(warmup, 7, false).expect("full W8");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Wide16);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::WarmupFullEscalateToW16
        );

        let wide = scheduler.plan_round(88).expect("qualified W16");
        assert_eq!(wide.physical_verify_width, 16);
        let (state, transition) = scheduler.finish_round(wide, 4, false).expect("partial W16");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Warmup);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::Wide16PartialFallbackToWarmup
        );

        let partial_warmup = scheduler.plan_round(83).expect("fallback W8");
        assert_eq!(partial_warmup.physical_verify_width, 8);
        scheduler
            .finish_round(partial_warmup, 3, false)
            .expect("partial fallback W8");
        assert_eq!(scheduler.state(), Gemma4Mtp12WidthScheduleState::Warmup);

        let full_warmup = scheduler.plan_round(79).expect("retry W8");
        scheduler
            .finish_round(full_warmup, 7, false)
            .expect("full retry W8");
        assert_eq!(scheduler.state(), Gemma4Mtp12WidthScheduleState::Wide16);
        assert_eq!(
            scheduler
                .plan_round(71)
                .expect("requalified W16")
                .physical_verify_width,
            16
        );
    }

    #[test]
    fn budget_tails_and_terminal_stops_hold_the_schedule_state() {
        let mut scheduler = Gemma4Mtp12WidthScheduler::new(16, true);
        let warmup = scheduler.plan_round(96).expect("initial W8");
        scheduler
            .finish_round(warmup, 7, false)
            .expect("qualify W16");

        let mut tails = Vec::new();
        for remaining in [15usize, 7, 3] {
            let plan = scheduler.plan_round(remaining).expect("admitted tail");
            tails.push(plan.physical_verify_width);
            let (state, transition) = scheduler
                .finish_round(plan, 0, false)
                .expect("partial budget tail");
            assert_eq!(state, Gemma4Mtp12WidthScheduleState::Wide16);
            assert_eq!(
                transition,
                Gemma4Mtp12WidthScheduleTransition::BudgetTailHold
            );
        }
        assert_eq!(tails, vec![8, 4, 2]);
        assert!(scheduler.plan_round(1).is_none());

        let mut stopped = Gemma4Mtp12WidthScheduler::new(16, true);
        let plan = stopped.plan_round(96).expect("terminal W8");
        let (state, transition) = stopped
            .finish_round(plan, 4, true)
            .expect("target-authoritative stop");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Warmup);
        assert_eq!(
            transition,
            Gemma4Mtp12WidthScheduleTransition::TerminalStopHold
        );
    }

    #[test]
    fn unset_schedule_preserves_fixed_width_and_never_affects_non_w16_runs() {
        let mut fixed_w16 = Gemma4Mtp12WidthScheduler::new(16, false);
        let plan = fixed_w16.plan_round(96).expect("fixed W16");
        assert_eq!(plan.physical_verify_width, 16);
        let (state, transition) = fixed_w16
            .finish_round(plan, 4, false)
            .expect("fixed partial W16");
        assert_eq!(state, Gemma4Mtp12WidthScheduleState::Fixed);
        assert_eq!(transition, Gemma4Mtp12WidthScheduleTransition::FixedWidth);
        assert_eq!(
            fixed_w16
                .plan_round(91)
                .expect("still fixed W16")
                .physical_verify_width,
            16
        );

        let fixed_w8 = Gemma4Mtp12WidthScheduler::new(8, true);
        assert_eq!(fixed_w8.state(), Gemma4Mtp12WidthScheduleState::Fixed);
        assert_eq!(
            fixed_w8
                .plan_round(96)
                .expect("fixed W8")
                .physical_verify_width,
            8
        );

        let mut malformed = Gemma4Mtp12WidthScheduler::new(16, true);
        let plan = malformed.plan_round(96).expect("initial W8");
        assert!(malformed
            .finish_round(plan, plan.logical_verify_width, false)
            .is_none());
    }

    #[test]
    fn tail_width_counts_the_anchor_in_the_remaining_budget() {
        assert_eq!(gemma4_mtp12_tail_verify_width(16, 17), Some(16));
        assert_eq!(gemma4_mtp12_tail_verify_width(16, 15), Some(8));
        assert_eq!(gemma4_mtp12_tail_verify_width(16, 7), Some(4));
        assert_eq!(gemma4_mtp12_tail_verify_width(16, 3), Some(2));
        assert_eq!(gemma4_mtp12_tail_verify_width(16, 1), None);
        assert_eq!(gemma4_mtp12_tail_verify_width(8, 9), Some(8));
        assert_eq!(gemma4_mtp12_tail_verify_width(8, 7), Some(4));
        assert_eq!(gemma4_mtp12_tail_verify_width(8, 3), Some(2));
        assert_eq!(gemma4_mtp12_tail_verify_width(8, 1), None);
        assert_eq!(gemma4_mtp12_tail_verify_width(4, 8), Some(4));
        assert_eq!(gemma4_mtp12_tail_verify_width(2, 8), Some(2));
    }

    #[test]
    fn mismatch_commit_includes_anchor_and_only_the_agreed_prefix() {
        let drafts = [10, 11, 12];
        let immediate = gemma4_mtp12_acceptance_decision(
            &drafts,
            &[20, 21, 22, 23],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(
            immediate,
            Gemma4Mtp12AcceptanceDecision {
                accepted_drafts: 0,
                committed_input_rows: 1,
                mismatch_draft_index: Some(0),
                stop_token: None,
                next_anchor_token: Some(20),
            }
        );

        let two = gemma4_mtp12_acceptance_decision(
            &drafts,
            &[10, 11, 20, 23],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(two.accepted_drafts, 2);
        assert_eq!(two.committed_input_rows, 3);
        assert_eq!(two.mismatch_draft_index, Some(2));
        assert_eq!(two.next_anchor_token, Some(20));
    }

    #[test]
    fn all_accepted_commits_every_candidate_and_uses_final_bonus() {
        let decision = gemma4_mtp12_acceptance_decision(
            &[10, 11, 12],
            &[10, 11, 12, 42],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(decision.accepted_drafts, 3);
        assert_eq!(decision.committed_input_rows, 4);
        assert_eq!(decision.mismatch_draft_index, None);
        assert_eq!(decision.stop_token, None);
        assert_eq!(decision.next_anchor_token, Some(42));
    }

    #[test]
    fn w16_acceptance_keeps_the_generic_commit_contract() {
        let drafts = (10u32..25).collect::<Vec<_>>();
        let mut target = drafts.clone();
        target.push(42);
        let decision = gemma4_mtp12_acceptance_decision(&drafts, &target, &[99])
            .expect("valid W16 target rows");
        assert_eq!(decision.accepted_drafts, 15);
        assert_eq!(decision.committed_input_rows, 16);
        assert_eq!(decision.mismatch_draft_index, None);
        assert_eq!(decision.stop_token, None);
        assert_eq!(decision.next_anchor_token, Some(42));
    }

    #[test]
    fn target_agreed_stop_is_neither_accepted_output_nor_committed_input() {
        let decision = gemma4_mtp12_acceptance_decision(
            &[10, 99, 12],
            &[10, 99, 12, 42],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(decision.accepted_drafts, 1);
        assert_eq!(decision.committed_input_rows, 2);
        assert_eq!(decision.mismatch_draft_index, None);
        assert_eq!(decision.stop_token, Some(99));
        assert_eq!(decision.next_anchor_token, None);
    }

    #[test]
    fn target_stop_on_mismatch_or_bonus_terminates_without_forwarding_it() {
        let mismatch = gemma4_mtp12_acceptance_decision(
            &[10, 11, 12],
            &[10, 99, 12, 42],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(mismatch.accepted_drafts, 1);
        assert_eq!(mismatch.committed_input_rows, 2);
        assert_eq!(mismatch.mismatch_draft_index, Some(1));
        assert_eq!(mismatch.stop_token, Some(99));
        assert_eq!(mismatch.next_anchor_token, None);

        let bonus = gemma4_mtp12_acceptance_decision(
            &[10, 11, 12],
            &[10, 11, 12, 99],
            &[99],
        )
        .expect("valid target rows");
        assert_eq!(bonus.accepted_drafts, 3);
        assert_eq!(bonus.committed_input_rows, 4);
        assert_eq!(bonus.stop_token, Some(99));
        assert_eq!(bonus.next_anchor_token, None);
    }

    #[test]
    fn malformed_target_row_count_fails_closed() {
        assert!(gemma4_mtp12_acceptance_decision(&[10, 11, 12], &[10, 11, 12], &[])
            .is_none());
    }

    #[test]
    fn rate_helpers_exclude_the_prefill_id_and_unverified_budget_tail_anchor() {
        let stats = Gemma4Mtp12MetalStats {
            rounds: 2,
            emitted_tokens: 6,
            committed_input_rows: 5,
            decode_us: 100_000,
            ..Gemma4Mtp12MetalStats::default()
        };
        assert_eq!(stats.decode_tokens_per_second(), 50.0);
        assert_eq!(stats.emitted_per_target_verify(), 2.5);
    }
}

#[cfg(target_os = "macos")]
impl Gemma4GpuRuntime {
    /// Load the model with the Q8 layer weights resident on the GPU. `max_positions`
    /// is the KV-cache capacity (must cover prompt + generated tokens).
    pub fn load(path: &Path, max_positions: usize) -> Result<Self> {
        let gguf = read_metadata(path)?;
        // BASALT Amendment 3 (D-B2 sidecar guard): this lane never ran the sidecar
        // check, so a sidecar-bearing NVFP4 file could compute wrong logits — refuse
        // it here, before any binding (cfg-independent, unit-tested on every host).
        // GABBRO M3-followup lifted the blanket NVFP4 refusal (the Metal resident lane
        // now runs NVFP4 layer projections via nvfp4_block_linear_row_ksplit_f32y_wire);
        // the D17/T5 NaN-sentinel guard moved to nvfp4_metal_sentinel_check below,
        // where the mmap is available to scan the wire bytes the raw upload reads.
        nvfp4_sidecar_check(&gguf.tensors)?;
        let config = LlamaModelConfig::from_gguf(&gguf)?;
        let g = config.gemma4.clone().ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture("not a gemma4 model".into())
        })?;
        let binding = Gemma4Binding::bind(&gguf, &config)?;
        let store = TensorStore::open(path, &gguf);
        // The GPU-resident decode kernels run the layer projections as Q8_0 (34-byte
        // wire blocks), Q4_0 (18-byte QAT wire blocks), or NVFP4 (36-byte 64-value
        // superblocks; GABBRO M3) — all parity-gated GPU GEMVs. The tied head is read
        // separately: Q8_0 runs inside the resident graph; Q6_K uses the strict ordered
        // file-backed Metal head when available and the held WireQuant CPU path as its
        // fail-closed fallback. Layer 0's attn_q is representative of the projection
        // format (the export quantizes every layer's projections alike).
        let layer_fmt = gemma4_metal_layer_fmt(
            store
                .descriptor(&binding.layers[0].attn_q.name)?
                .tensor_type,
        )?;
        let head_on_cpu = match store.descriptor(&binding.token_embedding.name)?.tensor_type {
            GgufTensorType::Q8_0 => false, // GPU Q8 head
            GgufTensorType::Q6K => true,   // ordered Metal Q6_K head or CPU fallback
            other => {
                return Err(BackendError::UnsupportedTensorType(format!(
                    "gemma4 GPU runtime supports a Q8_0 or Q6_K tied head; \
                     token embedding is {other:?}"
                )));
            }
        };
        let tokenizer = Tokenizer::from_gguf(&gguf)?;
        // The mmap backs token_embd + per_layer_token_embd (file-backed = evictable, so
        // it never forces the anonymous GPU WirePages to swap). GPU layer weights load
        // separately as page-aligned WirePages.
        let mmap = GgufWireMmap::map(path)?;
        // GABBRO M3-followup (D17/T5 fail-closed): the resident lane reads NVFP4 layer
        // wire RAW via WirePages (bypassing WireQuant::new's sentinel scan), so the
        // NaN-sentinel guard fires here — one pass over each NVFP4 tensor's UE4M3 scale
        // bytes before any GPU upload; 0x7F/0xFF refuses fail-closed, matching the CPU
        // wire lane. (nvfp4_sidecar_check for D-B2 already ran up top.)
        nvfp4_metal_sentinel_check(&gguf.tensors, &mmap)?;

        // Native Q4 is an explicit, exact-target sidecar. Presence of the env var
        // changes failure semantics: a wrong model, corrupt index/payload, missing
        // file, or unavailable native kernel is a hard refusal rather than silently
        // interpreting native bytes through the row-major fallback.
        let native_q4_sidecar_path =
            std::env::var_os(crate::gemma4_q4_sidecar::GEMMA4_Q4_NATIVE_SIDECAR_ENV)
                .map(std::path::PathBuf::from);
        let (native_q4_sidecar, native_q4_source_ranges, target_identity_preverified) =
            if let Some(sidecar_path) = native_q4_sidecar_path {
                if layer_fmt != crate::metal::GemmaWireFmt::Q4_0 {
                    return Err(BackendError::UnsupportedModelArchitecture(format!(
                        "{} requires dense Gemma 4 Q4_0 projection weights",
                        crate::gemma4_q4_sidecar::GEMMA4_Q4_NATIVE_SIDECAR_ENV
                    )));
                }
                if !crate::metal::gemma4_native_q4_kernel_family_admitted() {
                    return Err(BackendError::UnsupportedModelArchitecture(
                        "Gemma 4 native Q4 sidecar requested, but the complete f32/ordered/MMA Metal kernel family was not admitted"
                            .into(),
                    ));
                }
                let source_sha256 = gemma4_sha256_mmap_hex(&mmap).map_err(|detail| {
                    BackendError::InvalidTensorData(format!(
                        "Gemma 4 native Q4 source identity refused: {detail}"
                    ))
                })?;
                let sidecar = crate::gemma4_q4_sidecar::Gemma4Q4NativeSidecar::open(
                    &sidecar_path,
                    &gguf,
                    mmap.file_len(),
                    &source_sha256,
                )?;
                let ranges = sidecar.source_ranges().to_vec();
                // The exact-source SHA just faulted every GGUF page. Drop the Q4
                // source ranges before allocating their native replacements so the
                // two layouts do not overlap at peak resident pressure.
                for &(offset, len) in &ranges {
                    mmap.advise_dontneed_range(offset, len);
                }
                eprintln!(
                    "[gemma4-dense] native Q4 sidecar index admitted: {} ({} projections, {} bytes replacing GGUF Q4 pages)",
                    sidecar_path.display(),
                    sidecar.source_ranges().len(),
                    sidecar
                        .source_ranges()
                        .iter()
                        .map(|(_, len)| *len as u64)
                        .sum::<u64>(),
                );
                (Some(sidecar), ranges, true)
            } else {
                (None, Vec::new(), false)
            };

        let native_q4_enabled = native_q4_sidecar.is_some();
        if native_q4_enabled {
            // Warm only mappings that stay live at inference time: token_embd
            // and optional per_layer_token_embd. Whole-file readahead would
            // immediately recreate the replaced source-Q4 resident pages.
            let mut warm_ranges = Vec::with_capacity(2);
            for name in std::iter::once(binding.token_embedding.name.as_str()).chain(
                binding
                    .per_layer_token_embd
                    .as_ref()
                    .map(|descriptor| descriptor.name.as_str()),
            ) {
                let descriptor = store.descriptor(name)?;
                let offset = usize::try_from(descriptor.absolute_offset).map_err(|_| {
                    BackendError::InvalidTensorData(format!(
                        "embedding {name} offset does not fit this host"
                    ))
                })?;
                let len = usize::try_from(descriptor.n_bytes).map_err(|_| {
                    BackendError::InvalidTensorData(format!(
                        "embedding {name} length does not fit this host"
                    ))
                })?;
                warm_ranges.push((offset, len));
            }
            let mmap = mmap.clone();
            std::thread::spawn(move || {
                for (offset, len) in warm_ranges {
                    mmap.advise_willneed_range(offset, len);
                }
            });
        } else {
            // Preserve the established fallback byte-for-byte, including its
            // asynchronous whole-file warmup policy.
            let mmap = mmap.clone();
            std::thread::spawn(move || mmap.advise_willneed());
        }
        let native_q4_pages = native_q4_sidecar
            .as_ref()
            .map(|sidecar| sidecar.read_all_pages(&gguf))
            .transpose()?;
        if let Some(pages) = native_q4_pages.as_ref() {
            eprintln!(
                "[gemma4-dense] verified {} native Q4 resident payload hashes before Metal binding",
                pages.len()
            );
        }
        drop(native_q4_sidecar);
        let q8 = |name: &str| WireQuant::new(&store, &mmap, name);
        let f32t = |name: &str| -> Result<Vec<f32>> { Ok(store.load_cpu_f32(name)?.data) };

        let hidden = config.embedding_length as usize;
        let heads = config.attention_head_count as usize;
        let n_layers = config.block_count as usize;
        let vocab = config.vocab_size.unwrap() as usize;
        let eps = config.rms_norm_epsilon;
        let ple_dim = g.per_layer_input_dim as usize;
        let softcap = g.final_logit_softcapping.unwrap_or(0.0);

        let file = std::fs::File::open(path).map_err(|e| BackendError::Io {
            path: path.to_path_buf(),
            source: e,
        })?;
        let pages = |name: &str| -> Result<Arc<crate::wire_mmap::WirePages>> {
            let desc = store.descriptor(name)?;
            match native_q4_pages.as_ref() {
                Some(pages) => pages.get(name).cloned().ok_or_else(|| {
                    BackendError::InvalidTensorData(format!(
                        "validated native Q4 resident index has no projection {name}"
                    ))
                }),
                None => crate::wire_mmap::WirePages::read_from_file(
                    &file,
                    desc.absolute_offset,
                    desc.n_bytes as usize,
                ),
            }
        };

        let plan = g.layer_plan(n_layers, heads);
        let mut layers = Vec::with_capacity(n_layers);
        let mut ple = Vec::with_capacity(n_layers);
        let mut layer_scales = Vec::with_capacity(n_layers);
        let mut owns_kv = Vec::with_capacity(n_layers);
        let mut kv_source = Vec::with_capacity(n_layers);
        for (l, lb) in binding.layers.iter().enumerate() {
            let hd = g.head_dim_at(l) as usize;
            // Per-layer geometry (12B varies kv heads, E2B varies FFN width).
            let kv_heads = plan[l].kv_heads;
            let ffn_dim = g.ffn_length_at(l) as usize;
            let owns = plan[l].owns_kv;
            // Trimmed shared-KV exports (e.g. E4B QAT) omit attn_k / attn_k_norm /
            // attn_v on non-owning layers: those layers project no K/V and run
            // attention against the source layer's cache, so the resident attention
            // never reads these tensors. Pass never-read placeholders to keep the
            // layer shape uniform. A KV-owning layer that omits them is a real error.
            let q_pages_arc = pages(&lb.attn_q.name)?;
            let k_pages_arc = match &lb.attn_k {
                Some(d) => pages(&d.name)?,
                None if !owns => Arc::clone(&q_pages_arc),
                None => {
                    return Err(BackendError::UnsupportedTensorType(format!(
                        "gemma4 GPU runtime requires attn_k on KV-owning layers; \
                         layer {l} omits it"
                    )));
                }
            };
            let k_norm_v = match &lb.attn_k_norm {
                Some(d) => f32t(&d.name)?,
                None if !owns => vec![0.0f32; hd],
                None => {
                    return Err(BackendError::UnsupportedTensorType(format!(
                        "gemma4 GPU runtime requires attn_k_norm on KV-owning layers; \
                         layer {l} omits it"
                    )));
                }
            };
            let v_pages_arc = lb
                .attn_v
                .as_ref()
                .map(|descriptor| pages(&descriptor.name))
                .transpose()?;
            let o_pages_arc = pages(&lb.attn_output.name)?;
            let gate_pages_arc = pages(&lb.ffn_gate.name)?;
            let up_pages_arc = pages(&lb.ffn_up.name)?;
            let down_pages_arc = pages(&lb.ffn_down.name)?;
            let attn_norm = f32t(&lb.attn_norm.name)?;
            let q_norm = f32t(&lb.attn_q_norm.name)?;
            let post_attention_norm = f32t(&lb.post_attention_norm.name)?;
            let ffn_norm = f32t(&lb.ffn_norm.name)?;
            let post_ffw_norm = f32t(&lb.post_ffw_norm.name)?;
            let layer = if native_q4_enabled {
                crate::metal::Gemma4ResidentLayer::from_native_q4_pages(
                    layer_fmt,
                    attn_norm,
                    q_norm,
                    k_norm_v,
                    post_attention_norm,
                    ffn_norm,
                    post_ffw_norm,
                    &q_pages_arc,
                    &k_pages_arc,
                    v_pages_arc.as_ref(),
                    &o_pages_arc,
                    &gate_pages_arc,
                    &up_pages_arc,
                    &down_pages_arc,
                    heads,
                    kv_heads,
                    hd,
                    ffn_dim,
                    eps,
                )
            } else {
                crate::metal::Gemma4ResidentLayer::from_wire_pages(
                    layer_fmt,
                    attn_norm,
                    q_norm,
                    k_norm_v,
                    post_attention_norm,
                    ffn_norm,
                    post_ffw_norm,
                    &q_pages_arc,
                    &k_pages_arc,
                    v_pages_arc.as_ref(),
                    &o_pages_arc,
                    &gate_pages_arc,
                    &up_pages_arc,
                    &down_pages_arc,
                    heads,
                    kv_heads,
                    hd,
                    ffn_dim,
                    eps,
                )
            }
            .ok_or_else(|| {
                let detail = if native_q4_enabled {
                    "Metal native-Q4 kernel admission failed"
                } else {
                    "Metal unavailable"
                };
                BackendError::UnsupportedModelArchitecture(detail.into())
            })?;
            layers.push(layer);
            // layer_output_scale is unconditional in the reference. E-series
            // layers apply it inside the PLE encode; dense layers (no PLE) get
            // it standalone via `layer_scales`.
            let output_scale = lb
                .ple_output_scale
                .as_ref()
                .map(|d| f32t(&d.name))
                .transpose()?
                .and_then(|v| v.first().copied())
                .unwrap_or(1.0);
            layer_scales.push(output_scale);
            ple.push(match (&lb.ple_inp_gate, &lb.ple_proj, &lb.post_norm) {
                (Some(ig), Some(pj), Some(pn)) => Some(crate::metal::Gemma4ResidentPle {
                    inp_gate: f32t(&ig.name)?,
                    proj: f32t(&pj.name)?,
                    post_norm: f32t(&pn.name)?,
                    output_scale,
                }),
                _ => None,
            });
            owns_kv.push(plan[l].owns_kv);
            kv_source.push(plan[l].kv_source_layer);
        }

        // Norm/metadata loads can share filesystem pages with projection tails.
        // Narrow the replaced GGUF ranges once more after every native matrix is
        // resident; subsequent decode has no legitimate read from these bytes.
        for &(offset, len) in &native_q4_source_ranges {
            mmap.advise_dontneed_range(offset, len);
        }

        let token_embd = q8(&binding.token_embedding.name)?;
        let output_norm = f32t(&binding.output_norm.name)?;
        let q6k_gpu_head = if head_on_cpu && gemma4_dense_q6k_metal_head_enabled() {
            let desc = store.descriptor(&binding.token_embedding.name)?;
            let head = crate::metal::Gemma4Q6KHead::new_ordered_file_backed(
                Arc::clone(&mmap),
                desc.absolute_offset,
                desc.n_bytes as usize,
                &output_norm,
                vocab,
                softcap,
                eps,
            );
            if head.is_some() {
                eprintln!("[gemma4-dense] ordered file-backed Metal Q6_K head enabled");
            } else {
                eprintln!(
                    "[gemma4-dense] Metal Q6_K head unavailable; retaining CPU fallback"
                );
            }
            head
        } else {
            None
        };
        // QAT hybrid: don't hand the tied Q6_K table to the resident model's Q8 head —
        // pass an empty slice so no duplicate ~0.8 GiB buffer is uploaded. The ordered
        // no-copy Q6_K wrapper above and the CPU fallback share the original mmap.
        let head_wire: &[u8] = if head_on_cpu { &[] } else { token_embd.bytes() };
        if std::env::var("CAMELID_GEMMA4_DENSE_ORDERED_Q4")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        {
            eprintln!(
                "[gemma4-dense] strict ordered Q4_0 x Q8 K=1 projection universe requested"
            );
        }
        let model = crate::metal::Gemma4ResidentModel::new(
            layers,
            ple,
            layer_scales,
            owns_kv,
            kv_source,
            head_wire,
            output_norm.clone(),
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            1.0, // gemma folds the attention scale into the (QK-normed) query
        )
        .ok_or_else(|| BackendError::UnsupportedModelArchitecture("Metal unavailable".into()))?;

        let mut model = model;
        let per_layer_model_proj = binding
            .per_layer_model_proj
            .as_ref()
            .map(|d| f32t(&d.name))
            .transpose()?;
        let per_layer_proj_norm = binding
            .per_layer_proj_norm
            .as_ref()
            .map(|d| f32t(&d.name))
            .transpose()?;
        // Move the per-token pli computation onto the GPU (folded-constant matvec +
        // per-head norm + residual-add), eliminating the ~12ms/token CPU prep.
        if let (Some(proj), Some(pn)) = (&per_layer_model_proj, &per_layer_proj_norm) {
            model.set_pli(proj, pn, ple_dim);
        }

        let mtp12_target_identity = std::sync::OnceLock::new();
        if target_identity_preverified {
            mtp12_target_identity
                .set(Ok(()))
                .expect("fresh target identity lock accepts sidecar admission");
        }

        Ok(Self {
            model,
            tokenizer,
            per_layer_token_embd: binding
                .per_layer_token_embd
                .as_ref()
                .map(|d| q8(&d.name))
                .transpose()?,
            rope_factors: binding
                .rope_freqs
                .as_ref()
                .map(|d| f32t(&d.name))
                .transpose()?,
            token_embd,
            g,
            _mmap: mmap,
            hidden,
            ple_dim,
            n_layers,
            q6k_gpu_head,
            head_on_cpu,
            output_norm,
            vocab,
            eps,
            verifier_state: std::sync::Mutex::new(Gemma4DenseVerifierState {
                lane: Gemma4DenseSequenceLane::Unclaimed,
                logical_len: 0,
                next_ticket: 1,
                pending: None,
            }),
            mtp12_target_identity,
            native_q4_source_ranges,
        })
    }

    pub fn tokenizer(&self) -> &Tokenizer {
        &self.tokenizer
    }

    /// Begin a genuinely new sequence and release ownership of the shared
    /// resident KV cache arithmetic lane.  Physical bytes are retained, but
    /// the next established or ordered call must start at position zero and
    /// overwrites every cache row before it becomes visible.
    ///
    /// This is the only supported way to switch between established decode and
    /// ordered verification. It must not be called to fall back inside a live
    /// sequence, because the two paths intentionally use different projection
    /// arithmetic.
    pub fn reset_dense_verifier_sequence(&self) -> Result<()> {
        let mut state = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        state.reset_new_sequence();
        Ok(())
    }

    pub fn dense_verifier_logical_len(&self) -> Result<usize> {
        let state = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        if state.lane == Gemma4DenseSequenceLane::Established {
            return Err(BackendError::UnsupportedModelArchitecture(
                "shared target KV cache is in the established arithmetic lane".into(),
            ));
        }
        Ok(state.logical_len)
    }

    fn dense_verifier_row_inputs(
        &self,
        token: u32,
        position: usize,
    ) -> Result<(Vec<f32>, Vec<crate::metal::Gemma4TokenLayerInput>)> {
        if self.hidden != 3_840
            || self.n_layers != 48
            || self.ple_dim != 0
            || self.per_layer_token_embd.is_some()
        {
            return Err(BackendError::UnsupportedModelArchitecture(
                "ordered-Q4 verifier admits only the dense Gemma 4 12B row".into(),
            ));
        }
        let hidden = self.hidden;
        let h0: Vec<f32> = self
            .token_embd
            .dequantize_elements(token as usize * hidden, hidden)?
            .iter()
            .map(|value| value * (hidden as f32).sqrt())
            .collect();
        let filled = position.checked_add(1).ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture("verifier position overflow".into())
        })?;
        let sliding_window = self.g.sliding_window as usize;
        let mut inputs = Vec::with_capacity(self.n_layers);
        // Layers sharing a rotary configuration use identical tables at this
        // position. Compute the original expressions once for each configuration
        // instead of repeating powf/sin_cos across all 48 layers.
        let mut rotary_tables: Vec<(usize, u32, bool, Vec<f32>, Vec<f32>)> = Vec::new();
        for layer in 0..self.n_layers {
            let head_dim = self.g.head_dim_at(layer) as usize;
            let theta = self.g.rope_freq_base_at(layer);
            let half = head_dim / 2;
            let factors = if self.g.is_sliding_layer(layer) {
                None
            } else {
                self.rope_factors.as_deref()
            };
            let key = (head_dim, theta.to_bits(), factors.is_some());
            let (cos_t, sin_t) = if let Some((_, _, _, cos_t, sin_t)) = rotary_tables
                .iter()
                .find(|entry| (entry.0, entry.1, entry.2) == key)
            {
                (cos_t.clone(), sin_t.clone())
            } else {
                let (mut cos_t, mut sin_t) = (vec![0.0f32; half], vec![0.0f32; half]);
                for pair in 0..half {
                    let mut frequency = theta.powf(-(2.0 * pair as f32) / head_dim as f32);
                    if let Some(factors) = factors {
                        frequency /= factors[pair];
                    }
                    let (sin, cos) = (position as f32 * frequency).sin_cos();
                    cos_t[pair] = cos;
                    sin_t[pair] = sin;
                }
                rotary_tables.push((key.0, key.1, key.2, cos_t.clone(), sin_t.clone()));
                (cos_t, sin_t)
            };
            inputs.push(crate::metal::Gemma4TokenLayerInput {
                cos_t,
                sin_t,
                pli: Vec::new(),
                window_start: if self.g.is_sliding_layer(layer) {
                    filled.saturating_sub(sliding_window)
                } else {
                    0
                },
            });
        }
        Ok((h0, inputs))
    }

    /// Materialize K=1/2/4/8/16 target rows in the strict ordered-Q4 verifier
    /// universe and project all final states through the matching SPEC50 Q6_K
    /// head.  No logical cursor is advanced yet; the caller must commit an
    /// consumed input-row prefix with the returned ticket. Zero means the whole
    /// target call is being abandoned/retried, not an ordinary draft mismatch.
    pub fn verify_consecutive_greedy(
        &self,
        candidate_tokens: &[u32],
        start_position: usize,
    ) -> Result<Gemma4DenseVerifierBatch> {
        let (ticket, (greedy_ids, final_hidden, head_timing)) = self
            .with_consecutive_hidden_ordered_q4(
                candidate_tokens,
                start_position,
                |head, hidden_flat| {
                    let greedy_ids =
                        head.forward_argmax_spec50_batch(hidden_flat).ok_or_else(|| {
                            BackendError::UnsupportedModelArchitecture(
                                "SPEC50 K-wide Q6_K target head failed".into(),
                            )
                        })?;
                    let head_timing = head.last_spec50_timing();
                    if greedy_ids.len() != candidate_tokens.len() {
                        return Err(BackendError::RuntimeShapeMismatch(
                            "verifier head returned an invalid row count".into(),
                        ));
                    }
                    let final_hidden = hidden_flat
                        .chunks_exact(self.hidden)
                        .map(<[f32]>::to_vec)
                        .collect();
                    Ok((greedy_ids, final_hidden, head_timing))
                },
            )?;
        let decoder_gpu_us = crate::metal::GEMMA4_LAST_VERIFY_GPU_US
            .load(std::sync::atomic::Ordering::Relaxed);
        Ok(Gemma4DenseVerifierBatch {
            ticket,
            start_position,
            greedy_ids,
            final_hidden,
            head_timing,
            decoder_gpu_us,
        })
    }

    /// Execute causal target rows, allowing the caller to project only the
    /// predictions it needs. Hold the cursor lock through projection and issue
    /// a ticket only after both decoder and projection succeed.
    fn with_consecutive_hidden_ordered_q4<R>(
        &self,
        candidate_tokens: &[u32],
        start_position: usize,
        project: impl FnOnce(&crate::metal::Gemma4Q6KHead, &[f32]) -> Result<R>,
    ) -> Result<(u64, R)> {
        let width = candidate_tokens.len();
        if !gemma4_dense_verify_width_admitted(width) || !self.head_on_cpu {
            return Err(BackendError::UnsupportedModelArchitecture(
                "dense verifier requires K=1/2/4/8/16 and a Q6_K tied head".into(),
            ));
        }
        let head = self.q6k_gpu_head.as_ref().ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture(
                "SPEC50 verifier head unavailable (ordered Q6_K mapping was not admitted)".into(),
            )
        })?;
        let mut state = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        if !state.claim_ordered_verifier(start_position) {
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "shared target KV cache is owned by {:?}; ordered verification must claim a new sequence at position zero",
                state.lane,
            )));
        }
        if state.pending.is_some() || state.logical_len != start_position {
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "verifier cursor mismatch: logical_len={}, requested_start={}, pending={}",
                state.logical_len,
                start_position,
                state.pending.is_some(),
            )));
        }

        let mut h0_rows = Vec::with_capacity(width * self.hidden);
        let mut inputs_by_row = Vec::with_capacity(width);
        for (row, &token) in candidate_tokens.iter().enumerate() {
            let (h0, inputs) = self.dense_verifier_row_inputs(token, start_position + row)?;
            h0_rows.extend_from_slice(&h0);
            inputs_by_row.push(inputs);
        }
        let hidden_flat = self
            .model
            .verify_consecutive_hidden_ordered_q4(&h0_rows, &inputs_by_row, start_position)
            .ok_or_else(|| {
                BackendError::UnsupportedModelArchitecture(
                    "ordered-Q4 K-wide target verifier refused the model or dispatch".into(),
                )
            })?;
        if hidden_flat.len() != width * self.hidden {
            return Err(BackendError::RuntimeShapeMismatch(
                "verifier returned an invalid hidden row count".into(),
            ));
        }
        let result = project(head, &hidden_flat)?;
        let ticket = state
            .record_completed_batch(start_position, width)
            .ok_or_else(|| {
                BackendError::UnsupportedModelArchitecture(
                    "verifier cursor changed while the target batch was executing".into(),
                )
            })?;
        Ok((ticket, result))
    }

    /// Resolve a tentative verifier batch. `consumed_input_rows` counts target
    /// input rows physically accepted into the prefix, not accepted draft
    /// tokens or emitted outputs. For `[anchor, d1, ...]`, an immediate draft
    /// mismatch commits 1 (the anchor), accepting `m` drafts commits `1 + m`,
    /// and accepting every represented draft commits K; a bonus prediction is
    /// not a forwarded row. Zero is reserved for abort/retry via
    /// [`Self::rollback_verifier_batch`].
    ///
    /// Only the logical cursor changes; rejected physical KV tail rows are
    /// ignored and overwritten by the next ordered target call.
    pub fn commit_verifier_prefix(&self, ticket: u64, consumed_input_rows: usize) -> Result<usize> {
        let mut state = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        let pending = state.pending.ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture("no pending verifier batch".into())
        })?;
        if pending.ticket != ticket || consumed_input_rows > pending.width {
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "verifier commit mismatch: ticket={ticket}, consumed_inputs={consumed_input_rows}, pending={pending:?}",
            )));
        }
        state
            .resolve_prefix(ticket, consumed_input_rows)
            .ok_or_else(|| {
                BackendError::UnsupportedModelArchitecture(
                    "verifier prefix resolution overflowed or lost its ticket".into(),
                )
            })
    }

    /// Abandon an entire target batch without consuming even its anchor row.
    /// Ordinary speculative rejection should instead commit the consumed
    /// anchor/draft prefix with [`Self::commit_verifier_prefix`].
    pub fn rollback_verifier_batch(&self, ticket: u64) -> Result<usize> {
        self.commit_verifier_prefix(ticket, 0)
    }

    /// Build one authoritative normal step in the same arithmetic universe as
    /// K-wide verification, then commit that single row immediately.
    pub fn forward_greedy_ordered_q4(
        &self,
        token: u32,
        position: usize,
    ) -> Result<(u32, Vec<f32>)> {
        let batch = self.verify_consecutive_greedy(&[token], position)?;
        let next = batch.greedy_ids[0];
        let hidden = batch.final_hidden[0].clone();
        self.commit_verifier_prefix(batch.ticket, 1)?;
        Ok((next, hidden))
    }

    /// Start a new ordered-Q4 sequence and replay the exact tokenizer prompt
    /// (`encode(prompt, true, true)`) from position zero. Teacher-forced input
    /// rows are grouped into the largest admitted causal verifier chunks
    /// (16/8/4/2/1); unlike generated drafts, prompt rows never depend on the
    /// target's intermediate argmax, so every physical row is authoritative and
    /// committed. The final prompt prediction is the first output token; the
    /// matching final hidden row is returned for the first MTP recurrence.
    /// Only that final row is projected into the vocabulary. Set
    /// `CAMELID_GEMMA4_PREFILL_LAST_HEAD=0` to compare with all-row projection.
    pub fn prefill_ordered_q4(&self, prompt: &str) -> Result<Gemma4OrderedQ4Prefill> {
        let prompt_tokens = self.tokenizer.encode(prompt, true, true)?;
        if prompt_tokens.is_empty() {
            return Err(BackendError::UnsupportedModelArchitecture(
                "ordered-Q4 prompt encoding produced no input rows".into(),
            ));
        }
        self.reset_dense_verifier_sequence()?;
        let started = std::time::Instant::now();
        let mut first_greedy_id = 0u32;
        let mut pending_target_raw_hidden = Vec::new();
        let mut position = 0usize;
        let project_all_prompt_rows =
            std::env::var("CAMELID_GEMMA4_PREFILL_LAST_HEAD").as_deref() == Ok("0");
        while position < prompt_tokens.len() {
            let remaining = prompt_tokens.len() - position;
            let width = gemma4_ordered_q4_prefill_chunk_width(remaining)
                .expect("non-empty prompt tail has an admitted verifier width");
            if project_all_prompt_rows {
                let batch = self.verify_consecutive_greedy(
                    &prompt_tokens[position..position + width],
                    position,
                )?;
                let Some((&last_greedy_id, last_hidden)) =
                    batch.greedy_ids.last().zip(batch.final_hidden.last())
                else {
                    let _ = self.rollback_verifier_batch(batch.ticket);
                    return Err(BackendError::RuntimeShapeMismatch(format!(
                        "ordered-Q4 prompt batch W{width} returned no final prediction or hidden row"
                    )));
                };
                first_greedy_id = last_greedy_id;
                pending_target_raw_hidden = last_hidden.clone();
                position = self.commit_verifier_prefix(batch.ticket, width)?;
                continue;
            }
            let final_chunk = position + width == prompt_tokens.len();
            let (ticket, prediction) = self.with_consecutive_hidden_ordered_q4(
                &prompt_tokens[position..position + width],
                position,
                |head, hidden_flat| {
                    if !final_chunk {
                        return Ok(None);
                    }
                    // Prompt tokens are authoritative: only the very last
                    // prompt row needs a vocabulary projection. K1 uses the
                    // same ordered head arithmetic as each row of K2/4/8/16.
                    let last_hidden = &hidden_flat[hidden_flat.len() - self.hidden..];
                    let ids = head.forward_argmax_spec50_batch(last_hidden).ok_or_else(|| {
                        BackendError::UnsupportedModelArchitecture(
                            "SPEC50 final prompt Q6_K target head failed".into(),
                        )
                    })?;
                    if ids.len() != 1 {
                        return Err(BackendError::RuntimeShapeMismatch(
                            "final prompt head returned an invalid row count".into(),
                        ));
                    }
                    Ok(Some((ids[0], last_hidden.to_vec())))
                },
            )?;
            if let Some((id, hidden)) = prediction {
                first_greedy_id = id;
                pending_target_raw_hidden = hidden;
            }
            position = self.commit_verifier_prefix(ticket, width)?;
        }
        Ok(Gemma4OrderedQ4Prefill {
            prompt_token_count: prompt_tokens.len(),
            first_greedy_id,
            pending_target_raw_hidden,
            prefill_us: started.elapsed().as_micros(),
        })
    }

    /// K=1 ordered qualification runner. Stops use the complete Gemma stop set
    /// (metadata EOS/EOT/EOM plus recognized turn markers); a stop prediction is
    /// neither emitted nor forwarded. Prompt and decode timing are reported
    /// separately so generated-token throughput never includes prefill wall.
    pub fn generate_greedy_ordered_q4(
        &self,
        prompt: &str,
        max_new: usize,
    ) -> Result<Gemma4OrderedQ4Generation> {
        let prefill = self.prefill_ordered_q4(prompt)?;
        let stop_ids = gemma4_stop_token_ids(&self.tokenizer);
        let decode_started = std::time::Instant::now();
        let mut next = prefill.first_greedy_id;
        let mut generated = Vec::with_capacity(max_new);
        let mut position = prefill.prompt_token_count;
        let mut decode_forward_count = 0usize;
        for generated_index in 0..max_new {
            if stop_ids.contains(&next) {
                break;
            }
            generated.push(next);
            if generated_index + 1 < max_new {
                (next, _) = self.forward_greedy_ordered_q4(next, position)?;
                position += 1;
                decode_forward_count += 1;
            }
        }
        let decode_us = decode_started.elapsed().as_micros();
        let text = self.tokenizer.decode(&generated, true)?;
        Ok(Gemma4OrderedQ4Generation {
            text,
            token_ids: generated,
            prompt_token_count: prefill.prompt_token_count,
            prefill_us: prefill.prefill_us,
            decode_forward_count,
            decode_us,
        })
    }

    /// Run the established full-logit lane and ordered K=1 lane on fresh
    /// sequences, failing at the first greedy-id divergence. This is the
    /// mandatory whole-target admission gate for SPEC50; component-level kernel
    /// parity alone is not sufficient.
    pub fn qualify_ordered_q4_k1(
        &self,
        prompt: &str,
        max_new: usize,
    ) -> Result<Gemma4OrderedQ4Generation> {
        self.reset_dense_verifier_sequence()?;
        let (_, established) = self.generate_greedy(prompt, max_new)?;
        let ordered = self.generate_greedy_ordered_q4(prompt, max_new)?;
        if established != ordered.token_ids {
            let mismatch = established
                .iter()
                .zip(&ordered.token_ids)
                .position(|(left, right)| left != right)
                .unwrap_or_else(|| established.len().min(ordered.token_ids.len()));
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "ordered-Q4 K1 qualification diverged at output {mismatch}: established={:?}, ordered={:?}",
                established.get(mismatch),
                ordered.token_ids.get(mismatch),
            )));
        }
        Ok(ordered)
    }

    /// Admit the exact target bytes backing this runtime for the official 12B
    /// MTP assistant.  The hash is computed over the retained read-only mmap,
    /// never by reopening a potentially replaced source path, and the result is
    /// cached (including failure) for the lifetime of the runtime.
    fn require_mtp12_target_identity(&self) -> Result<()> {
        let admission = self.mtp12_target_identity.get_or_init(|| {
            let actual = gemma4_sha256_mmap_hex(&self._mmap)?;
            if actual != crate::metal::GEMMA4_12B_QAT_Q4_0_TARGET_SHA256 {
                return Err(format!(
                    "loaded target {} has SHA-256 {actual}, expected {}",
                    self._mmap.path().display(),
                    crate::metal::GEMMA4_12B_QAT_Q4_0_TARGET_SHA256,
                ));
            }
            // A lazy identity pass faults the entire GGUF. Shed the replaced
            // source Q4 pages once, as part of that one-time admission—not on
            // every speculative round that reads the cached OnceLock result.
            for &(offset, len) in &self.native_q4_source_ranges {
                self._mmap.advise_dontneed_range(offset, len);
            }
            Ok(())
        });
        match admission {
            Ok(()) => Ok(()),
            Err(detail) => Err(BackendError::UnsupportedModelArchitecture(format!(
                "Gemma 4 12B MTP target identity refused: {detail}"
            ))),
        }
    }

    /// Run (or retrieve) the exact 12B target SHA admission and return its wall
    /// time.  Callers may invoke this before loading the ~846 MB assistant so
    /// the first 6.98 GB sequential hash does not overlap peak resident pressure.
    /// Every assistant proposal still repeats the cached check defensively.
    pub fn admit_mtp12_target_identity(&self) -> Result<u128> {
        let started = std::time::Instant::now();
        self.require_mtp12_target_identity()?;
        Ok(started.elapsed().as_micros())
    }

    /// Propose up to 15 MTP12 drafts against the exact ordered target prefix.
    ///
    /// This is the only runtime bridge into the resident assistant.  It holds
    /// the target sequence-state mutex across the complete synchronous Metal
    /// call, requires an ordered cache with no unresolved target batch, and
    /// requires `position == logical_len`.  The loaded target mmap must match
    /// the pinned 12B QAT SHA before its scoped Q6_K table is aliased.  Target
    /// layer 46/47 cache views and the table alias are nested callbacks, so no
    /// borrowed Metal buffer can escape.
    ///
    /// `pending_target_raw_hidden` is the raw post-layer state associated with
    /// the last committed target row.  The target's exact weighted output RMS
    /// norm is applied once here; the assistant keeps all later recurrent rows
    /// resident and must not receive this raw state directly.
    pub fn propose_mtp12_chain_ordered_q4(
        &self,
        assistant: &mut crate::metal::Gemma4Mtp12AssistantMetal,
        anchor_token: u32,
        pending_target_raw_hidden: &[f32],
        position: usize,
        draft_k: usize,
    ) -> Result<crate::metal::Gemma4Mtp12ChainProposal> {
        self.require_mtp12_target_identity()?;
        if pending_target_raw_hidden.len() != self.hidden
            || pending_target_raw_hidden.iter().any(|value| !value.is_finite())
        {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 MTP raw target hidden has width {} (expected {}) or non-finite values",
                pending_target_raw_hidden.len(),
                self.hidden,
            )));
        }
        if !(1..=crate::metal::GEMMA4_12B_MTP_MAX_DRAFTS).contains(&draft_k) {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 MTP draft width is {draft_k}, expected 1..={}",
                crate::metal::GEMMA4_12B_MTP_MAX_DRAFTS,
            )));
        }
        let normalized_hidden = rms_norm(
            pending_target_raw_hidden,
            Some(&self.output_norm),
            self.eps,
        );
        if normalized_hidden.iter().any(|value| !value.is_finite()) {
            return Err(BackendError::RuntimeShapeMismatch(
                "Gemma 4 MTP normalized target hidden contains non-finite values".into(),
            ));
        }

        let sequence = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        if sequence.lane != Gemma4DenseSequenceLane::OrderedVerifier
            || sequence.pending.is_some()
            || sequence.logical_len != position
        {
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "MTP assistant requires an ordered committed target prefix: lane={:?}, logical_len={}, requested_position={position}, pending={}",
                sequence.lane,
                sequence.logical_len,
                sequence.pending.is_some(),
            )));
        }

        let head = self.q6k_gpu_head.as_ref().ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture(
                "MTP assistant requires the strict mapped Q6_K target head".into(),
            )
        })?;
        let kv_scoped = head
            .with_full_table_device(
                crate::metal::GEMMA4_12B_QAT_Q4_0_TARGET_SHA256,
                |target_table| {
                    self.model.with_kv_device_views(
                        &[
                            crate::metal::GEMMA4_12B_MTP_SLIDING_HOST_LAYER,
                            crate::metal::GEMMA4_12B_MTP_FULL_HOST_LAYER,
                        ],
                        |views| {
                            if views.len() != 2
                                || views[0].source_layer
                                    != crate::metal::GEMMA4_12B_MTP_SLIDING_HOST_LAYER
                                || views[1].source_layer
                                    != crate::metal::GEMMA4_12B_MTP_FULL_HOST_LAYER
                            {
                                return Err(BackendError::UnsupportedModelArchitecture(
                                    "MTP target KV callback did not return exact source layers 46/47"
                                        .into(),
                                ));
                            }
                            let sliding_view = &views[0];
                            let sliding = crate::metal::Gemma4Mtp12DeviceKv {
                                key: crate::metal::Gemma4Mtp12MetalBufferView {
                                    buffer: sliding_view.key,
                                    byte_offset: sliding_view.byte_offset,
                                    byte_len: sliding_view.byte_len,
                                },
                                value: crate::metal::Gemma4Mtp12MetalBufferView {
                                    buffer: sliding_view.value,
                                    byte_offset: sliding_view.byte_offset,
                                    byte_len: sliding_view.byte_len,
                                },
                                source_layer: sliding_view.source_layer,
                                kv_heads: sliding_view.kv_heads,
                                head_dim: sliding_view.head_dim,
                                max_positions: sliding_view.max_positions,
                            };
                            let full_view = &views[1];
                            let full = crate::metal::Gemma4Mtp12DeviceKv {
                                key: crate::metal::Gemma4Mtp12MetalBufferView {
                                    buffer: full_view.key,
                                    byte_offset: full_view.byte_offset,
                                    byte_len: full_view.byte_len,
                                },
                                value: crate::metal::Gemma4Mtp12MetalBufferView {
                                    buffer: full_view.value,
                                    byte_offset: full_view.byte_offset,
                                    byte_len: full_view.byte_len,
                                },
                                source_layer: full_view.source_layer,
                                kv_heads: full_view.kv_heads,
                                head_dim: full_view.head_dim,
                                max_positions: full_view.max_positions,
                            };
                            assistant.propose_chain_from_cpu_hidden(
                                anchor_token,
                                &normalized_hidden,
                                target_table,
                                sliding,
                                full,
                                position,
                                position,
                                draft_k,
                            )
                        },
                    )
                },
            )
            .ok_or_else(|| {
                BackendError::UnsupportedModelArchitecture(
                    "MTP target Q6_K full-table scope refused pinned identity or geometry".into(),
                )
            })?;
        let proposal = kv_scoped.ok_or_else(|| {
            BackendError::UnsupportedModelArchitecture(
                "MTP target could not expose resident KV source layers 46/47".into(),
            )
        })?;
        // Keep `sequence` alive through the complete synchronous assistant wait;
        // dropping it earlier would permit the target prefix to change while the
        // assistant is reading its borrowed KV buffers.
        drop(sequence);
        proposal
    }

    /// Lossless greedy MTP12 generation for strict target verifier widths
    /// 2/4/8/16 (assistant draft counts 1/3/7/15).  The default is fixed width.
    /// With `CAMELID_GEMMA4_MTP_W16_WARMUP8=1`, configured W16 starts at W8,
    /// promotes after a full W8 round, and conservatively falls back after a
    /// partial W16 round. The mutually-exclusive one-shot selector runs W8 once,
    /// then holds W16; when 10..=15 outputs remain it reserves the final bonus
    /// anchor, verifies the logical `remaining - 1` prefix in a causally padded
    /// physical W16 call, and never compares or commits padding. Otherwise near
    /// the output budget the scheduled width steps down through 16/8/4/2; a final
    /// single-token budget is satisfied by the already-predicted anchor without
    /// forwarding it.
    ///
    /// The target remains authoritative at every position.  An immediate
    /// mismatch commits one anchor row, accepting `m` drafts commits `1 + m`
    /// rows, and an all-accepted round commits all logical candidate rows. Padded
    /// physical rows are never eligible for comparison or commit. Stop ids
    /// are never emitted or committed as input rows, including a stop proposed
    /// by the assistant and confirmed by the target.
    pub fn generate_greedy_mtp12_ordered_q4(
        &self,
        assistant: &mut crate::metal::Gemma4Mtp12AssistantMetal,
        prompt: &str,
        max_new: usize,
        verify_width: usize,
    ) -> Result<Gemma4Mtp12MetalGeneration> {
        match self.generate_greedy_mtp12_ordered_q4_controlled(
            assistant,
            prompt,
            max_new,
            verify_width,
            None::<fn(&str)>,
            || false,
        )? {
            Gemma4Mtp12MetalGenerationOutcome::Complete(generation) => Ok(generation),
            Gemma4Mtp12MetalGenerationOutcome::Cancelled(_) => unreachable!(),
        }
    }

    /// Serve-safe streaming counterpart to
    /// [`Self::generate_greedy_mtp12_ordered_q4`]. Text is released only after
    /// the target verifier has committed the corresponding logical rows. The
    /// cancellation predicate is sampled at round boundaries, where neither a
    /// target verifier ticket nor a partially-consumed assistant proposal is
    /// live. A cancelled request returns its partial native receipt rather than
    /// turning a disconnected HTTP owner into an inference failure.
    pub fn generate_greedy_mtp12_ordered_q4_streaming_cancellable<
        F: FnMut(&str),
        C: FnMut() -> bool,
    >(
        &self,
        assistant: &mut crate::metal::Gemma4Mtp12AssistantMetal,
        prompt: &str,
        max_new: usize,
        verify_width: usize,
        on_delta: F,
        should_cancel: C,
    ) -> Result<Gemma4Mtp12MetalGenerationOutcome> {
        self.generate_greedy_mtp12_ordered_q4_controlled(
            assistant,
            prompt,
            max_new,
            verify_width,
            Some(on_delta),
            should_cancel,
        )
    }

    /// Replay a caller-supplied render draft only after this exact target has
    /// independently proved every token greedy for `prompt`. The first token is
    /// checked against the target's post-prefill argmax; later tokens are
    /// teacher-forced through causal verifier batches and compared with the
    /// target prediction at their own positions before their text is released.
    ///
    /// This is deliberately not a cache or a trusted presentation shortcut: a
    /// single out-of-vocabulary id, stop id, or target mismatch fails closed.
    /// The assistant handle is retained solely to bind the same admitted lane
    /// identity and resident ledger into the terminal MTP12 diagnostics.
    pub fn render_target_verified_mtp12_ordered_q4_streaming_cancellable<
        F: FnMut(&str),
        C: FnMut() -> bool,
    >(
        &self,
        assistant: &crate::metal::Gemma4Mtp12AssistantMetal,
        prompt: &str,
        render_draft_token_ids: &[u32],
        verify_width: usize,
        mut on_delta: F,
        mut should_cancel: C,
    ) -> Result<Gemma4Mtp12MetalGenerationOutcome> {
        if !matches!(verify_width, 2 | 4 | 8 | 16) {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 target-verified render width is {verify_width}, expected 2, 4, 8, or 16"
            )));
        }
        if render_draft_token_ids.is_empty() {
            return Err(BackendError::RuntimeShapeMismatch(
                "Gemma 4 target-verified render draft must contain at least one token".into(),
            ));
        }
        let vocab_size = self.vocab;
        if let Some((index, token_id)) = render_draft_token_ids
            .iter()
            .copied()
            .enumerate()
            .find(|(_, token_id)| *token_id as usize >= vocab_size)
        {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 target-verified render draft token {index} has id {token_id}, outside vocabulary size {vocab_size}"
            )));
        }

        let target_identity_us = self.admit_mtp12_target_identity()?;
        let prefill = self.prefill_ordered_q4(prompt)?;
        let stop_ids = gemma4_stop_token_ids(&self.tokenizer);
        if let Some((index, token_id)) = render_draft_token_ids
            .iter()
            .copied()
            .enumerate()
            .find(|(_, token_id)| stop_ids.contains(token_id))
        {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 target-verified render draft contains terminal stop id {token_id} at output index {index}"
            )));
        }
        if prefill.first_greedy_id != render_draft_token_ids[0] {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 target-verified render draft mismatched at output index 0: draft {}, target {}",
                render_draft_token_ids[0], prefill.first_greedy_id,
            )));
        }

        let mut stats = Gemma4Mtp12MetalStats {
            configured_verify_width: verify_width,
            width_schedule: Gemma4Mtp12WidthScheduleProvenance {
                selector: "camelid_target_verified_render_draft_token_ids",
                selector_value: Some(verify_width.to_string()),
                enabled: true,
                active_for_configured_width: true,
                warmup_verify_width: None,
                padded_tail_policy: None,
                policy: "caller_render_draft;target_greedy_verified_before_emit;largest_exact_tail_width",
            },
            target_identity_us,
            prefill_us: prefill.prefill_us,
            ..Gemma4Mtp12MetalStats::default()
        };
        let decode_started = std::time::Instant::now();
        let mut text_stream = Gemma4Mtp12StableTextStream::default();
        let mut generated = Vec::with_capacity(render_draft_token_ids.len());
        generated.push(render_draft_token_ids[0]);
        text_stream.push_verified(
            &render_draft_token_ids[..1],
            |ids| self.tokenizer.decode(ids, true),
            &mut on_delta,
        )?;

        let mut verified_outputs = 1usize;
        let mut cancelled = false;
        while verified_outputs < render_draft_token_ids.len() {
            if should_cancel() {
                cancelled = true;
                break;
            }
            let remaining_predictions = render_draft_token_ids.len() - verified_outputs;
            let width = gemma4_ordered_q4_prefill_chunk_width(remaining_predictions)
                .expect("non-empty render tail has an admitted verifier width")
                .min(verify_width);
            let input_start = verified_outputs - 1;
            let candidates = &render_draft_token_ids[input_start..input_start + width];
            let expected = &render_draft_token_ids[verified_outputs..verified_outputs + width];
            let position = prefill.prompt_token_count + input_start;
            let verify_started = std::time::Instant::now();
            let target_batch = self.verify_consecutive_greedy(candidates, position)?;
            let target_verify_us = verify_started.elapsed().as_micros();
            if target_batch.greedy_ids.len() != width {
                let _ = self.rollback_verifier_batch(target_batch.ticket);
                return Err(BackendError::RuntimeShapeMismatch(format!(
                    "Gemma 4 target-verified render W{width} returned {} target predictions",
                    target_batch.greedy_ids.len(),
                )));
            }
            if let Some(relative) = target_batch
                .greedy_ids
                .iter()
                .zip(expected)
                .position(|(target, draft)| target != draft)
            {
                let _ = self.rollback_verifier_batch(target_batch.ticket);
                let output_index = verified_outputs + relative;
                return Err(BackendError::RuntimeShapeMismatch(format!(
                    "Gemma 4 target-verified render draft mismatched at output index {output_index}: draft {}, target {}",
                    expected[relative], target_batch.greedy_ids[relative],
                )));
            }
            self.commit_verifier_prefix(target_batch.ticket, width)?;

            generated.extend_from_slice(expected);
            text_stream.push_verified(
                expected,
                |ids| self.tokenizer.decode(ids, true),
                &mut on_delta,
            )?;
            verified_outputs += width;
            stats.rounds += 1;
            stats.drafted += width as u64;
            stats.accepted_drafts += width as u64;
            stats.committed_input_rows += width as u64;
            stats.target_verify_rows += width as u64;
            stats.target_verify_us = stats.target_verify_us.saturating_add(target_verify_us);
            if width < verify_width {
                stats.budget_tail_rounds += 1;
            }
        }

        stats.decode_us = decode_started.elapsed().as_micros();
        stats.emitted_tokens = generated.len() as u64;
        let text = self.tokenizer.decode(&generated, true)?;
        if text != text_stream.emitted_text {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "MTP target-verified render stream differed from final target decode: streamed {} bytes, final {} bytes",
                text_stream.emitted_text.len(),
                text.len(),
            )));
        }
        let generation = Gemma4Mtp12MetalGeneration {
            text,
            token_ids: generated,
            prompt_token_count: prefill.prompt_token_count,
            target_model_sha256: crate::metal::GEMMA4_12B_QAT_Q4_0_TARGET_SHA256,
            assistant_model_sha256: crate::metal::GEMMA4_12B_MTP_ASSISTANT_SHA256,
            assistant_source_path: assistant.source_path().to_path_buf(),
            assistant_resident_ledger: assistant.resident_ledger().into(),
            stats,
        };
        Ok(if cancelled {
            Gemma4Mtp12MetalGenerationOutcome::Cancelled(generation)
        } else {
            Gemma4Mtp12MetalGenerationOutcome::Complete(generation)
        })
    }

    fn generate_greedy_mtp12_ordered_q4_controlled<
        F: FnMut(&str),
        C: FnMut() -> bool,
    >(
        &self,
        assistant: &mut crate::metal::Gemma4Mtp12AssistantMetal,
        prompt: &str,
        max_new: usize,
        verify_width: usize,
        mut on_delta: Option<F>,
        mut should_cancel: C,
    ) -> Result<Gemma4Mtp12MetalGenerationOutcome> {
        if !matches!(verify_width, 2 | 4 | 8 | 16) {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "Gemma 4 MTP target verify width is {verify_width}, expected 2, 4, 8, or 16"
            )));
        }

        let adaptive_selector_value = std::env::var_os(GEMMA4_MTP12_W16_WARMUP8_ENV)
            .map(|value| {
                value.into_string().map_err(|value| {
                    BackendError::RuntimeShapeMismatch(format!(
                        "{GEMMA4_MTP12_W16_WARMUP8_ENV} must be UTF-8 and exactly 0 or 1; got {value:?}"
                    ))
                })
            })
            .transpose()?;
        let one_shot_selector_value =
            std::env::var_os(GEMMA4_MTP12_W16_ONESHOT_W8_PAD16_ENV)
                .map(|value| {
                    value.into_string().map_err(|value| {
                        BackendError::RuntimeShapeMismatch(format!(
                            "{GEMMA4_MTP12_W16_ONESHOT_W8_PAD16_ENV} must be UTF-8 and exactly 0 or 1; got {value:?}"
                        ))
                    })
                })
                .transpose()?;
        let adaptive_enabled = gemma4_mtp12_w16_warmup8_policy(adaptive_selector_value.as_deref())
            .map_err(BackendError::RuntimeShapeMismatch)?;
        let one_shot_enabled =
            gemma4_mtp12_w16_oneshot_w8_pad16_policy(one_shot_selector_value.as_deref())
                .map_err(BackendError::RuntimeShapeMismatch)?;
        if adaptive_enabled && one_shot_enabled {
            return Err(BackendError::RuntimeShapeMismatch(format!(
                "{GEMMA4_MTP12_W16_WARMUP8_ENV} and {GEMMA4_MTP12_W16_ONESHOT_W8_PAD16_ENV} are mutually exclusive"
            )));
        }
        let adaptive_active = adaptive_enabled && verify_width == 16;
        let one_shot_active = one_shot_enabled && verify_width == 16;
        let mut width_scheduler = if one_shot_active {
            Gemma4Mtp12WidthScheduler::new_one_shot_w8_padded_w16(verify_width)
                .expect("active one-shot schedule is configured W16")
        } else {
            Gemma4Mtp12WidthScheduler::new(verify_width, adaptive_enabled)
        };

        let target_identity_us = self.admit_mtp12_target_identity()?;
        let prefill = self.prefill_ordered_q4(prompt)?;
        let stop_ids = gemma4_stop_token_ids(&self.tokenizer);
        let mut stats = Gemma4Mtp12MetalStats {
            configured_verify_width: verify_width,
            width_schedule: Gemma4Mtp12WidthScheduleProvenance {
                selector: if one_shot_enabled {
                    GEMMA4_MTP12_W16_ONESHOT_W8_PAD16_ENV
                } else {
                    GEMMA4_MTP12_W16_WARMUP8_ENV
                },
                selector_value: if one_shot_enabled {
                    one_shot_selector_value
                } else {
                    adaptive_selector_value
                },
                enabled: adaptive_enabled || one_shot_enabled,
                active_for_configured_width: adaptive_active || one_shot_active,
                warmup_verify_width: (adaptive_active || one_shot_active).then_some(8),
                padded_tail_policy: one_shot_active.then_some(
                    "remaining_10_through_15_reserves_bonus_anchor; logical_remaining_minus_1; physical_w16; repeat_anchor_padding",
                ),
                policy: if one_shot_active {
                    "one_shot_w8_then_w16; partial_acceptance_does_not_fallback; padded_w16_tail"
                } else if adaptive_active {
                    "start_warmup; full_warmup_to_w16; partial_w16_to_warmup; tails_hold_state"
                } else {
                    "fixed_width"
                },
            },
            target_identity_us,
            prefill_us: prefill.prefill_us,
            ..Gemma4Mtp12MetalStats::default()
        };
        let mut generated = Vec::with_capacity(max_new);
        let mut anchor_token = prefill.first_greedy_id;
        let mut pending_target_raw_hidden = prefill.pending_target_raw_hidden;
        let mut position = prefill.prompt_token_count;
        let decode_started = std::time::Instant::now();
        let mut text_stream = Gemma4Mtp12StableTextStream::default();
        let mut cancelled = false;

        while generated.len() < max_new {
            if should_cancel() {
                cancelled = true;
                break;
            }
            if stop_ids.contains(&anchor_token) {
                stats.terminal_stop_token = Some(anchor_token);
                break;
            }
            let remaining = max_new - generated.len();
            let Some(round_plan) = width_scheduler.plan_round(remaining) else {
                // `anchor_token` is already the target's exact next output.  At
                // a one-token budget tail there is no reason to forward it.
                generated.push(anchor_token);
                if let Some(on_delta) = on_delta.as_mut() {
                    text_stream.push_verified(
                        &[anchor_token],
                        |ids| self.tokenizer.decode(ids, true),
                        on_delta,
                    )?;
                }
                break;
            };
            let logical_width = round_plan.logical_verify_width;
            let physical_width = round_plan.physical_verify_width;
            let draft_k = logical_width - 1;
            let assistant_started = std::time::Instant::now();
            let draft_proposal = self.propose_mtp12_chain_ordered_q4(
                assistant,
                anchor_token,
                &pending_target_raw_hidden,
                position,
                draft_k,
            )?;
            let assistant_call_us = assistant_started.elapsed().as_micros();
            if draft_proposal.tokens.len() != draft_k {
                return Err(BackendError::RuntimeShapeMismatch(format!(
                    "MTP assistant returned {} drafts for requested K={draft_k}",
                    draft_proposal.tokens.len()
                )));
            }

            let (candidates, padding_candidate_ids) =
                gemma4_mtp12_materialize_candidate_rows(
                    round_plan,
                    anchor_token,
                    &draft_proposal.tokens,
                )
                .ok_or_else(|| {
                    BackendError::RuntimeShapeMismatch(format!(
                        "MTP candidate materialization refused logical W{logical_width} / physical W{physical_width} / drafts {draft_k}"
                    ))
                })?;
            let verify_started = std::time::Instant::now();
            let target_batch = self.verify_consecutive_greedy(&candidates, position)?;
            let target_verify_us = verify_started.elapsed().as_micros();
            let logical_target_greedy_ids = (target_batch.greedy_ids.len() == physical_width)
                .then(|| target_batch.greedy_ids[..logical_width].to_vec());
            let decision = logical_target_greedy_ids.as_deref().and_then(|target_ids| {
                gemma4_mtp12_acceptance_decision(
                    &draft_proposal.tokens,
                    target_ids,
                    &stop_ids,
                )
            })
            .ok_or_else(|| {
                // The verifier contract guarantees K predictions, but leave no
                // pending ticket behind if a future implementation violates it.
                let _ = self.rollback_verifier_batch(target_batch.ticket);
                BackendError::RuntimeShapeMismatch(format!(
                    "MTP target returned {} predictions for logical W{logical_width} / physical W{physical_width} / {} drafts",
                    target_batch.greedy_ids.len(),
                    draft_proposal.tokens.len()
                ))
            })?;
            let hidden_index = decision.committed_input_rows - 1;
            let next_raw_hidden = target_batch.final_hidden.get(hidden_index).cloned();
            let committed_position = self.commit_verifier_prefix(
                target_batch.ticket,
                decision.committed_input_rows,
            )?;

            let mut emitted_token_ids = Vec::with_capacity(1 + decision.accepted_drafts);
            emitted_token_ids.push(anchor_token);
            emitted_token_ids
                .extend_from_slice(&draft_proposal.tokens[..decision.accepted_drafts]);
            if generated.len() + emitted_token_ids.len() > max_new {
                return Err(BackendError::RuntimeShapeMismatch(
                    "MTP adaptive verifier emitted past the requested output budget".into(),
                ));
            }
            generated.extend_from_slice(&emitted_token_ids);
            if let Some(on_delta) = on_delta.as_mut() {
                text_stream.push_verified(
                    &emitted_token_ids,
                    |ids| self.tokenizer.decode(ids, true),
                    on_delta,
                )?;
            }

            stats.rounds += 1;
            stats.drafted += draft_k as u64;
            stats.accepted_drafts += decision.accepted_drafts as u64;
            stats.committed_input_rows += decision.committed_input_rows as u64;
            stats.target_verify_rows += physical_width as u64;
            stats.assistant_us = stats.assistant_us.saturating_add(assistant_call_us);
            stats.assistant_gpu_us = stats
                .assistant_gpu_us
                .saturating_add(draft_proposal.timing.gpu_us);
            stats.assistant_kernel_us = stats
                .assistant_kernel_us
                .saturating_add(draft_proposal.timing.kernel_us);
            stats.target_verify_us = stats.target_verify_us.saturating_add(target_verify_us);
            let target_head_us = u128::from(target_batch.head_timing.wall_us);
            let target_head_gpu_us = u128::from(target_batch.head_timing.gpu_us);
            let target_decoder_gpu_us = u128::from(target_batch.decoder_gpu_us);
            stats.target_head_us = stats.target_head_us.saturating_add(target_head_us);
            stats.target_head_gpu_us = stats.target_head_gpu_us.saturating_add(target_head_gpu_us);
            stats.target_decoder_gpu_us = stats
                .target_decoder_gpu_us
                .saturating_add(target_decoder_gpu_us);
            if round_plan.budget_truncated {
                stats.budget_tail_rounds += 1;
            }
            let (schedule_state_after, schedule_transition) = width_scheduler
                .finish_round(
                    round_plan,
                    decision.accepted_drafts,
                    decision.stop_token.is_some(),
                )
                .ok_or_else(|| {
                    BackendError::RuntimeShapeMismatch(format!(
                        "MTP width state refused scheduled W{} / logical W{} / physical W{} / accepted {}",
                        round_plan.scheduled_verify_width,
                        round_plan.logical_verify_width,
                        round_plan.physical_verify_width,
                        decision.accepted_drafts,
                    ))
                })?;
            stats.trace.push(Gemma4Mtp12MetalRoundReceipt {
                position,
                anchor_token,
                configured_verify_width: verify_width,
                scheduled_verify_width: round_plan.scheduled_verify_width,
                logical_verify_width: logical_width,
                physical_verify_width: physical_width,
                verifier_width: physical_width,
                padding_candidate_ids,
                budget_truncated: round_plan.budget_truncated,
                schedule_state_before: round_plan.state_before,
                schedule_state_after,
                schedule_transition,
                drafts: draft_proposal.tokens.clone(),
                target_greedy_ids: target_batch.greedy_ids.clone(),
                accepted_drafts: decision.accepted_drafts,
                committed_input_rows: decision.committed_input_rows,
                emitted_token_ids,
                mismatch_draft_index: decision.mismatch_draft_index,
                stop_token: decision.stop_token,
                next_anchor_token: decision.next_anchor_token,
                assistant_call_us,
                assistant_timing: draft_proposal.timing.into(),
                assistant_ledger: draft_proposal.ledger.into(),
                target_verify_us,
                target_head_us,
                target_head_gpu_us,
                target_decoder_gpu_us,
            });

            if let Some(stop) = decision.stop_token {
                stats.terminal_stop_token = Some(stop);
                break;
            }
            anchor_token = decision.next_anchor_token.ok_or_else(|| {
                BackendError::RuntimeShapeMismatch(
                    "MTP acceptance produced neither a next anchor nor a stop".into(),
                )
            })?;
            pending_target_raw_hidden = next_raw_hidden.ok_or_else(|| {
                BackendError::RuntimeShapeMismatch(
                    "MTP target omitted the raw hidden row for the committed prefix".into(),
                )
            })?;
            position = committed_position;
        }
        stats.decode_us = decode_started.elapsed().as_micros();
        stats.emitted_tokens = generated.len() as u64;
        let text = if on_delta.is_some() {
            let final_text = self.tokenizer.decode(&generated, true)?;
            if final_text != text_stream.emitted_text {
                return Err(BackendError::RuntimeShapeMismatch(format!(
                    "MTP stable text stream differed from final target decode: streamed {} bytes, final {} bytes",
                    text_stream.emitted_text.len(),
                    final_text.len(),
                )));
            }
            final_text
        } else {
            self.tokenizer.decode(&generated, true)?
        };
        let generation = Gemma4Mtp12MetalGeneration {
            text,
            token_ids: generated,
            prompt_token_count: prefill.prompt_token_count,
            target_model_sha256: crate::metal::GEMMA4_12B_QAT_Q4_0_TARGET_SHA256,
            assistant_model_sha256: crate::metal::GEMMA4_12B_MTP_ASSISTANT_SHA256,
            assistant_source_path: assistant.source_path().to_path_buf(),
            assistant_resident_ledger: assistant.resident_ledger().into(),
            stats,
        };
        Ok(if cancelled {
            Gemma4Mtp12MetalGenerationOutcome::Cancelled(generation)
        } else {
            Gemma4Mtp12MetalGenerationOutcome::Complete(generation)
        })
    }

    /// Complete model-specific stop set used by both established and ordered
    /// generation.
    pub fn stop_token_ids(&self) -> Vec<u32> {
        gemma4_stop_token_ids(&self.tokenizer)
    }

    /// Scoped no-copy target embedding row for the MTP assistant.
    pub(crate) fn with_q6k_embedding_row_device<R>(
        &self,
        token: u32,
        callback: impl FnOnce(&metal::BufferRef, u64, u64) -> R,
    ) -> Option<R> {
        self.q6k_gpu_head
            .as_ref()?
            .with_selected_row_device(token, callback)
    }

    /// Scoped f32 target KV views (notably layers 46 and 47 for MTP-12).
    pub(crate) fn with_target_kv_device_views<R>(
        &self,
        source_layers: &[usize],
        callback: impl FnOnce(&[crate::metal::Gemma4ResidentKvDeviceView<'_>]) -> R,
    ) -> Option<R> {
        self.model.with_kv_device_views(source_layers, callback)
    }

    fn project_q6k_logits_cpu(&self, hidden: &[f32]) -> Vec<f32> {
        let last = rms_norm(hidden, Some(&self.output_norm), self.eps);
        let mut logits = self.token_embd.matvec(self.hidden, self.vocab, &last);
        if let Some(cap) = self.g.final_logit_softcapping {
            soft_cap_in_place(&mut logits, cap);
        }
        logits
    }

    /// Run one token's forward on the GPU and return the next-token logits.
    fn forward(&self, token: u32, position: usize) -> Result<Vec<f32>> {
        let mut sequence = self.verifier_state.lock().map_err(|_| {
            BackendError::UnsupportedModelArchitecture("verifier state poisoned".into())
        })?;
        if !sequence.claim_established(position) {
            return Err(BackendError::UnsupportedModelArchitecture(format!(
                "established target row refused: lane={:?}, cursor={}, requested_position={}; reset only at a new-sequence boundary",
                sequence.lane,
                sequence.logical_len,
                position,
            )));
        }
        let t_prep = std::time::Instant::now();
        let hidden = self.hidden;
        let ple_dim = self.ple_dim;
        let ple_total = self.n_layers * ple_dim;
        let filled = position + 1;
        // Scaled input embedding (CPU gather).
        let h0: Vec<f32> = self
            .token_embd
            .dequantize_elements(token as usize * hidden, hidden)?
            .iter()
            .map(|v| v * (hidden as f32).sqrt())
            .collect();
        // PLE `pli` is computed ON the GPU (Gemma4ResidentModel::set_pli) — the CPU
        // only gathers this token's per_layer_token_embd row, with the gemma constants
        // (ple_dim^0.5 * FRAC_1_SQRT_2) folded in so the GPU just residual-adds it.
        let ti: Vec<f32> = if let Some(te) = self.per_layer_token_embd.as_ref() {
            let scale = (ple_dim as f32).sqrt() * std::f32::consts::FRAC_1_SQRT_2;
            te.dequantize_elements(token as usize * ple_total, ple_total)?
                .iter()
                .map(|v| v * scale)
                .collect()
        } else {
            Vec::new()
        };
        // Per-layer RoPE tables (dual θ, per-type head_dim) + sliding window start.
        let win = self.g.sliding_window as usize;
        let inputs: Vec<crate::metal::Gemma4TokenLayerInput> = (0..self.n_layers)
            .map(|l| {
                let hd = self.g.head_dim_at(l) as usize;
                let theta = self.g.rope_freq_base_at(l);
                let half = hd / 2;
                // Frequency factors (proportional rope) on FULL layers only.
                let factors = if self.g.is_sliding_layer(l) {
                    None
                } else {
                    self.rope_factors.as_deref()
                };
                let (mut cos_t, mut sin_t) = (vec![0f32; half], vec![0f32; half]);
                for i in 0..half {
                    let mut freq = theta.powf(-(2.0 * i as f32) / hd as f32);
                    if let Some(factors) = factors {
                        freq /= factors[i];
                    }
                    let (s, c) = (position as f32 * freq).sin_cos();
                    cos_t[i] = c;
                    sin_t[i] = s;
                }
                let window_start = if self.g.is_sliding_layer(l) {
                    filled.saturating_sub(win)
                } else {
                    0
                };
                crate::metal::Gemma4TokenLayerInput {
                    cos_t,
                    sin_t,
                    pli: Vec::new(), // pli now computed on the GPU; not passed per-layer
                    window_start,
                }
            })
            .collect();
        let prep_us = t_prep.elapsed().as_micros();
        let t_gpu = std::time::Instant::now();
        // All-Q8 path: the resident graph encodes the head and returns logits directly.
        // QAT path: the graph returns final hidden, then the strict ordered Metal Q6_K
        // wrapper runs the tied projection. Every construction/dispatch/policy failure
        // falls back to the original CPU projection unchanged.
        let logits = if self.head_on_cpu {
            let last_hidden = self
                .model
                .forward_token_hidden(&h0, &inputs, &ti, position)
                .ok_or_else(|| {
                    BackendError::UnsupportedModelArchitecture("gpu forward failed".into())
                })?;
            if gemma4_dense_q6k_metal_head_enabled() {
                if let Some(logits) = self
                    .q6k_gpu_head
                    .as_ref()
                    .and_then(|head| head.forward(&last_hidden))
                {
                    logits
                } else {
                    self.project_q6k_logits_cpu(&last_hidden)
                }
            } else {
                self.project_q6k_logits_cpu(&last_hidden)
            }
        } else {
            self.model
                .forward_token(&h0, &inputs, &ti, position)
                .ok_or_else(|| {
                    BackendError::UnsupportedModelArchitecture("gpu forward failed".into())
                })?
        };
        if std::env::var("CAMELID_GEMMA4_GPU_TIMING").is_ok() {
            PREP_US.fetch_add(prep_us as u64, std::sync::atomic::Ordering::Relaxed);
            GPU_US.fetch_add(
                t_gpu.elapsed().as_micros() as u64,
                std::sync::atomic::Ordering::Relaxed,
            );
            FWD_N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
        if !sequence.complete_established(position) {
            return Err(BackendError::UnsupportedModelArchitecture(
                "established target cursor changed while the GPU row was executing".into(),
            ));
        }
        drop(sequence);
        Ok(logits)
    }

    /// Greedy generate up to `max_new` tokens from `prompt` on the GPU.
    #[allow(clippy::explicit_counter_loop)] // `pos` is an absolute sequence index
    pub fn generate_greedy(&self, prompt: &str, max_new: usize) -> Result<(String, Vec<u32>)> {
        let prompt_tokens = self.tokenizer.encode(prompt, true, true)?;
        let eot = gemma4_stop_token_ids(&self.tokenizer);
        let mut logits = Vec::new();
        for (pos, &tok) in prompt_tokens.iter().enumerate() {
            logits = self.forward(tok, pos)?;
        }
        let mut generated = Vec::new();
        let mut pos = prompt_tokens.len();
        for _ in 0..max_new {
            let next = logits
                .iter()
                .enumerate()
                .max_by(|a, b| a.1.total_cmp(b.1))
                .map(|(i, _)| i as u32)
                .unwrap();
            if eot.contains(&next) {
                break;
            }
            generated.push(next);
            logits = self.forward(next, pos)?;
            pos += 1;
        }
        if std::env::var("CAMELID_GEMMA4_GPU_TIMING").is_ok() {
            use std::sync::atomic::Ordering::Relaxed;
            let (n, prep, gpu) = (
                FWD_N.load(Relaxed).max(1),
                PREP_US.load(Relaxed),
                GPU_US.load(Relaxed),
            );
            eprintln!(
                "[gpu-timing] {n} forwards: cpu prep avg {}us, gpu avg {}us (total {}us/fwd)",
                prep / n,
                gpu / n,
                (prep + gpu) / n
            );
        }
        let text = self.tokenizer.decode(&generated, true)?;
        Ok((text, generated))
    }
}

#[cfg(target_os = "macos")]
static PREP_US: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(target_os = "macos")]
static GPU_US: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(target_os = "macos")]
static FWD_N: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Per-layer RMSNorm weights kept resident on the GPU (small; ~tens of KB/layer).
#[cfg(feature = "cuda")]
struct Gemma4LayerNormsDev {
    attn_norm: cudarc::driver::CudaSlice<f32>,
    q_norm: cudarc::driver::CudaSlice<f32>,
    k_norm: Option<cudarc::driver::CudaSlice<f32>>,
    post_attn_norm: cudarc::driver::CudaSlice<f32>,
    ffn_norm: cudarc::driver::CudaSlice<f32>,
    post_ffw_norm: cudarc::driver::CudaSlice<f32>,
    // MoE-only: the dense shared-expert branch's own post-norm (`post_norm_1`) and
    // the sparse expert-sum post-norm (`post_norm_2`). Resident so the whole MoE
    // dense + compose runs on the GPU (M4). `None` on dense rows.
    moe_pre_norm_2: Option<cudarc::driver::CudaSlice<f32>>,
    moe_post_norm_1: Option<cudarc::driver::CudaSlice<f32>>,
    moe_post_norm_2: Option<cudarc::driver::CudaSlice<f32>>,
}

/// Per-layer projection weights kept resident on the GPU in the SoA layout
/// `q8_gemv` reads (uploaded once at load). For E4B Q8 this is ~4–4.5 GB and fits
/// a 6 GB card because the big embeddings (`token_embd`, `per_layer_token_embd`)
/// stay on the CPU for the head + PLE gather. `k`/`v` exist only on owning layers;
/// `v` is `None` on V-less layers (V reuses the K projection).
#[cfg(feature = "cuda")]
struct Gemma4LayerWeightsDev {
    q: cudarc::driver::CudaSlice<u8>,
    k: Option<cudarc::driver::CudaSlice<u8>>,
    v: Option<cudarc::driver::CudaSlice<u8>>,
    o: cudarc::driver::CudaSlice<u8>,
    gate: cudarc::driver::CudaSlice<u8>,
    up: cudarc::driver::CudaSlice<u8>,
    down: cudarc::driver::CudaSlice<u8>,
    // Per-projection quant lane (mixed Q4_0 file: Q4_0 projections + Q4_1 ffn_down).
    q_q: GemmaLayerQuant,
    k_q: GemmaLayerQuant,
    v_q: GemmaLayerQuant,
    o_q: GemmaLayerQuant,
    gate_q: GemmaLayerQuant,
    up_q: GemmaLayerQuant,
    down_q: GemmaLayerQuant,
}

/// Quant lane of a resident gemma4 layer projection. All consume Q8_0
/// activations; Q8_0 weights are SoA-repacked, Q4_0/Q4_1/NVFP4 are raw wire.
#[cfg(feature = "cuda")]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum GemmaLayerQuant {
    Q8_0,
    Q4_0,
    Q4_1,
    Nvfp4,
    Q6K,
    Q4K,
}

#[cfg(feature = "cuda")]
impl GemmaLayerQuant {
    fn from_wire(f: WireFormat) -> Self {
        match f {
            WireFormat::Q8_0 => Self::Q8_0,
            WireFormat::Q4_0 => Self::Q4_0,
            WireFormat::Q4_1 => Self::Q4_1,
            WireFormat::Nvfp4 => Self::Nvfp4,
            WireFormat::Q6K => Self::Q6K,
            WireFormat::Q4K => Self::Q4K,
            other => {
                panic!("gemma4 layer projection quant {other:?} unsupported (Q8_0/Q4_0/Q4_1/NVFP4/Q6_K/Q4_K)")
            }
        }
    }
}

/// Per-projection GEMV dispatch for the gemma4 resident layer loop. All lanes take the
/// shared Q8_0 activation buffers (`d_ins`/`d_inq`) and `blocks_per_row = cols/32`; the
/// weight is SoA Q8_0 or raw Q4_0/Q4_1 wire. Mirrors `cuda_resident::dispatch_gemv` but
/// for the gemma4 Q8_0-activation lanes only.
#[cfg(feature = "cuda")]
#[allow(clippy::too_many_arguments)]
fn gemma_proj_gemv(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernels: &crate::cuda_resident::CudaResidentKernels,
    quant: GemmaLayerQuant,
    in_scales: &cudarc::driver::CudaSlice<f32>,
    in_quants: &cudarc::driver::CudaSlice<i8>,
    in_scales_k: &cudarc::driver::CudaSlice<f32>,
    in_quants_k: &cudarc::driver::CudaSlice<i8>,
    weight: &cudarc::driver::CudaView<'_, u8>,
    rows: usize,
    blocks_per_row: usize,
    out: &mut cudarc::driver::CudaSlice<f32>,
) -> std::result::Result<(), cudarc::driver::DriverError> {
    match quant {
        GemmaLayerQuant::Q8_0 => crate::cuda_resident::launch_gemv(
            s,
            &kernels.gemv,
            in_scales,
            in_quants,
            weight,
            rows,
            blocks_per_row,
            out,
        ),
        // Projection weights reach VRAM through `upw`, which repacks Q4_0 into the
        // quants-first SoA layout, so this dispatch must drive the SoA kernel. The
        // launcher is shared: identical geometry, shared-memory layout and argument
        // list — only the kernel differs. The routed-expert GEMVs deliberately keep
        // `q4_0_gemv`/`q4_0_gemv_routed`, because the SSER arena is filled by DMA
        // straight from raw `.cghost` records (that layout is a separate change).
        GemmaLayerQuant::Q4_0 => crate::cuda_resident::launch_q4_0_gemv(
            s,
            if gemma4_q4_0_soa_enabled() {
                &kernels.q4_0_gemv_soa
            } else {
                &kernels.q4_0_gemv
            },
            in_scales,
            in_quants,
            weight,
            rows,
            blocks_per_row,
            out,
            0,
        ),
        GemmaLayerQuant::Q4_1 => crate::cuda_resident::launch_q4_1_gemv(
            s,
            &kernels.q4_1_gemv,
            in_scales,
            in_quants,
            weight,
            rows,
            blocks_per_row,
            out,
            0,
        ),
        // BASALT Phase 4: NVFP4 raw-wire GEMV. `launch_nvfp4_gemv` returns a typed
        // Nvfp4LaunchError; the odd-block variant is the I-k-div lane guard and is
        // structurally unreachable here (the parse boundary refuses non-%64 NVFP4
        // first-dims at load — k_div_fixture_trips_parse_refusal — so every gemma4
        // projection reaching the CUDA GEMV has an even Q8_0-block count), matching
        // the codebase's guard-then-unreachable idiom (matvec's Q5_K arm).
        GemmaLayerQuant::Nvfp4 => match crate::cuda_resident::launch_nvfp4_gemv(
            s,
            &kernels.nvfp4_gemv,
            in_scales,
            in_quants,
            weight,
            rows,
            blocks_per_row,
            out,
            0,
        ) {
            Ok(()) => Ok(()),
            Err(crate::cuda_resident::Nvfp4LaunchError::Driver(e)) => Err(e),
            Err(crate::cuda_resident::Nvfp4LaunchError::OddBlocksPerRow(bpr)) => unreachable!(
                "gemma4 NVFP4 projection reached the CUDA GEMV with an odd Q8_0-block count \
                 {bpr} (in_dim % 64 != 0); the parse boundary refuses non-%64 NVFP4 tensors \
                 before load"
            ),
        },
        GemmaLayerQuant::Q6K => crate::cuda_resident::launch_q6k_gemv(
            s,
            &kernels.q6k_gemv,
            in_scales_k,
            in_quants_k,
            weight,
            rows,
            blocks_per_row / 8,
            out,
            0,
        ),
        GemmaLayerQuant::Q4K => crate::cuda_resident::launch_q4k_gemv(
            s,
            &kernels.q4k_gemv,
            in_scales_k,
            in_quants_k,
            weight,
            rows,
            blocks_per_row / 8,
            out,
            0,
        ),
    }
}

/// K-token counterpart of [`gemma_proj_gemv`] for the exact Gemma 4 verifier.
///
/// Common Q4_0 weights use the same load-time SoA policy as scalar decode;
/// Q4_1 remains raw wire. K-quants consume the parallel Q8_K activation buffers.
/// NVFP4 intentionally has no arm: eligibility declines it before allocating or
/// mutating KV, preserving the scalar verifier as the correctness fallback.
#[cfg(feature = "cuda")]
#[allow(clippy::too_many_arguments)]
fn gemma_proj_gemm_batched(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernels: &crate::cuda_resident::CudaResidentKernels,
    quant: GemmaLayerQuant,
    in_scales: &cudarc::driver::CudaSlice<f32>,
    in_quants: &cudarc::driver::CudaSlice<i8>,
    in_scales_k: &cudarc::driver::CudaSlice<f32>,
    in_quants_k: &cudarc::driver::CudaSlice<i8>,
    weight: &cudarc::driver::CudaSlice<u8>,
    rows: usize,
    cols: usize,
    tokens: usize,
    out: &mut cudarc::driver::CudaSlice<f32>,
) -> Result<()> {
    let driver_result = match quant {
        GemmaLayerQuant::Q8_0 => {
            if !cols.is_multiple_of(32) {
                return Err(BackendError::InvalidModelMetadata(format!(
                    "Gemma 4 K-wide Q8 projection input {cols} is not divisible by 32"
                )));
            }
            crate::cuda_resident::launch_gemm_batched(
                s,
                &kernels.gemm_batched,
                in_scales,
                in_quants,
                weight,
                rows,
                cols / 32,
                tokens,
                out,
            )
        }
        GemmaLayerQuant::Q4_0 => {
            if !cols.is_multiple_of(32) {
                return Err(BackendError::InvalidModelMetadata(format!(
                    "Gemma 4 K-wide Q4_0 projection input {cols} is not divisible by 32"
                )));
            }
            if gemma4_q4_0_soa_enabled() {
                if let Some(kernel) = kernels.gemma4_mtp_dense_q4_0_imma_kernel() {
                    crate::cuda_resident::launch_q4_0_gemm_batched_soa_imma(
                        s,
                        kernel,
                        in_scales,
                        in_quants,
                        weight,
                        rows,
                        cols / 32,
                        tokens,
                        out,
                    )
                } else {
                    let (kernel, zero_shared) = kernels.gemma4_mtp_dense_q4_0_gemm_kernel();
                    if zero_shared {
                        crate::cuda_resident::launch_q4_0_gemm_batched_soa(
                            s,
                            kernel,
                            in_scales,
                            in_quants,
                            weight,
                            rows,
                            cols / 32,
                            tokens,
                            out,
                        )
                    } else {
                        crate::cuda_resident::launch_q4_0_gemm_batched_soa_shared(
                            s,
                            kernel,
                            in_scales,
                            in_quants,
                            weight,
                            rows,
                            cols / 32,
                            tokens,
                            out,
                        )
                    }
                }
            } else {
                crate::cuda_resident::launch_q4_0_gemm_batched(
                    s,
                    &kernels.q4_0_gemm_batched,
                    in_scales,
                    in_quants,
                    weight,
                    rows,
                    cols / 32,
                    tokens,
                    out,
                )
            }
        }
        GemmaLayerQuant::Q4_1 => {
            if !cols.is_multiple_of(32) {
                return Err(BackendError::InvalidModelMetadata(format!(
                    "Gemma 4 K-wide Q4_1 projection input {cols} is not divisible by 32"
                )));
            }
            crate::cuda_resident::launch_q4_1_gemm_batched(
                s,
                &kernels.q4_1_gemm_batched,
                in_scales,
                in_quants,
                weight,
                rows,
                cols / 32,
                tokens,
                out,
            )
        }
        GemmaLayerQuant::Q4K | GemmaLayerQuant::Q6K => {
            if !cols.is_multiple_of(256) {
                return Err(BackendError::InvalidModelMetadata(format!(
                    "Gemma 4 K-wide {quant:?} projection input {cols} is not divisible by 256"
                )));
            }
            let (kernel, aux_lanes) = match quant {
                GemmaLayerQuant::Q4K => (&kernels.q4k_gemm_batched, 9),
                GemmaLayerQuant::Q6K => kernels.gemma4_mtp_dense_q6_gemm_kernel(),
                _ => unreachable!(),
            };
            crate::cuda_resident::launch_kquant_gemm_batched(
                s,
                kernel,
                in_scales_k,
                in_quants_k,
                weight,
                rows,
                cols / 256,
                tokens,
                aux_lanes,
                out,
            )
        }
        GemmaLayerQuant::Nvfp4 => {
            return Err(BackendError::UnsupportedGguf(
                "Gemma 4 K-wide CUDA verifier has no batched NVFP4 projection; use the scalar verifier"
                    .into(),
            ));
        }
    };
    driver_result.map_err(cu)
}

#[cfg(feature = "cuda")]
#[allow(clippy::too_many_arguments)]
fn gemma4_launch_rope_batched(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernel: &cudarc::driver::CudaFunction,
    values: &mut cudarc::driver::CudaSlice<f32>,
    cos: &cudarc::driver::CudaView<'_, f32>,
    sin: &cudarc::driver::CudaView<'_, f32>,
    heads: usize,
    head_dim: usize,
    per_token_dim: usize,
    k_tokens: usize,
) -> std::result::Result<(), cudarc::driver::DriverError> {
    use cudarc::driver::{LaunchConfig, PushKernelArg};
    let half = head_dim / 2;
    let total = (k_tokens * heads * half) as u32;
    let config = LaunchConfig {
        grid_dim: (total.div_ceil(128).max(1), 1, 1),
        block_dim: (128, 1, 1),
        shared_mem_bytes: 0,
    };
    let (heads, head_dim, rope_dim, per_token_dim, half, k_tokens, pairing) = (
        heads as i32,
        head_dim as i32,
        head_dim as i32,
        per_token_dim as i32,
        half as i32,
        k_tokens as i32,
        1i32,
    );
    let mut builder = s.launch_builder(kernel);
    builder
        .arg(values)
        .arg(cos)
        .arg(sin)
        .arg(&heads)
        .arg(&head_dim)
        .arg(&rope_dim)
        .arg(&per_token_dim)
        .arg(&half)
        .arg(&k_tokens)
        .arg(&pairing);
    unsafe { builder.launch(config) }.map(|_| ())
}

#[cfg(feature = "cuda")]
fn gemma4_launch_geglu(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernel: &cudarc::driver::CudaFunction,
    gate: &cudarc::driver::CudaSlice<f32>,
    up: &cudarc::driver::CudaSlice<f32>,
    out: &mut cudarc::driver::CudaSlice<f32>,
    values: usize,
) -> std::result::Result<(), cudarc::driver::DriverError> {
    use cudarc::driver::{LaunchConfig, PushKernelArg};
    let config = LaunchConfig {
        grid_dim: ((values as u32).div_ceil(256).max(1), 1, 1),
        block_dim: (256, 1, 1),
        shared_mem_bytes: 0,
    };
    let values = values as i32;
    let mut builder = s.launch_builder(kernel);
    builder.arg(gate).arg(up).arg(out).arg(&values);
    unsafe { builder.launch(config) }.map(|_| ())
}

/// Launch the per-assignment GeGLU+quantize for the contiguous assignment range
/// `[assignment_offset, assignment_offset + assignments)` (offset 0 with the
/// full count is the whole batch). `assignment_ids` is the identity map, so the
/// offset sub-view's *values* are the absolute assignment indices of the range,
/// and the kernel reads and writes at absolute positions — a two-pass split
/// touches exactly the rows a full pass would.
#[cfg(feature = "cuda")]
#[allow(clippy::too_many_arguments)]
fn gemma4_launch_geglu_quantize_assignments_range(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernel: &cudarc::driver::CudaFunction,
    gate_up: &cudarc::driver::CudaSlice<f32>,
    assignment_ids: &cudarc::driver::CudaSlice<i32>,
    quants: &mut cudarc::driver::CudaSlice<i8>,
    scales: &mut cudarc::driver::CudaSlice<f32>,
    nff: usize,
    assignment_offset: usize,
    assignments: usize,
) -> std::result::Result<(), cudarc::driver::DriverError> {
    use cudarc::driver::{LaunchConfig, PushKernelArg};
    if assignments == 0 {
        return Ok(());
    }
    let blocks = nff / 32;
    let warps = 8u32;
    let config = LaunchConfig {
        grid_dim: (
            (blocks as u32).div_ceil(warps).max(1),
            assignments as u32,
            1,
        ),
        block_dim: (warps * 32, 1, 1),
        shared_mem_bytes: 0,
    };
    let ids = assignment_ids.slice(assignment_offset..);
    let (nff, blocks, assignments) = (nff as i32, blocks as i32, assignments as i32);
    let mut builder = s.launch_builder(kernel);
    builder
        .arg(gate_up)
        .arg(&ids)
        .arg(quants)
        .arg(scales)
        .arg(&nff)
        .arg(&blocks)
        .arg(&assignments);
    unsafe { builder.launch(config) }.map(|_| ())
}

#[cfg(feature = "cuda")]
fn gemma4_launch_soft_cap(
    s: &std::sync::Arc<cudarc::driver::CudaStream>,
    kernel: &cudarc::driver::CudaFunction,
    values: &mut cudarc::driver::CudaSlice<f32>,
    len: usize,
    cap: f32,
) -> std::result::Result<(), cudarc::driver::DriverError> {
    use cudarc::driver::{LaunchConfig, PushKernelArg};
    let config = LaunchConfig {
        grid_dim: ((len as u32).div_ceil(256).max(1), 1, 1),
        block_dim: (256, 1, 1),
        shared_mem_bytes: 0,
    };
    let len = len as i32;
    let mut builder = s.launch_builder(kernel);
    builder.arg(values).arg(&len).arg(&cap);
    unsafe { builder.launch(config) }.map(|_| ())
}

/// Per-layer PLE weights resident on the GPU (small f32 matrices), so the
/// per-layer PLE injection runs entirely on the device — no host round-trip.
#[cfg(feature = "cuda")]
struct Gemma4LayerPleDev {
    inp_gate: cudarc::driver::CudaSlice<f32>,
    proj: cudarc::driver::CudaSlice<f32>,
    post_norm: cudarc::driver::CudaSlice<f32>,
    output_scale: f32,
}

/// A captured decode CUDA graph, wrapped Send: cudarc's `CudaGraph` is not `Send`,
/// but the engine lives behind a `Mutex` in `Arc<Gemma4ServeRuntime>` (one request
/// at a time), so the raw graph handle is only ever touched under the lock.
#[cfg(feature = "cuda")]
struct SendGraph(cudarc::driver::CudaGraph);
#[cfg(feature = "cuda")]
unsafe impl Send for SendGraph {}

#[cfg(feature = "cuda")]
fn cu(e: cudarc::driver::DriverError) -> BackendError {
    BackendError::InvalidModelMetadata(format!("gemma4 cuda: {e}"))
}

/// Repack a GGUF Q8_0 weight tensor (34-byte blocks: f16 scale + 32 i8) into the
/// compact SoA layout `q8_gemv` reads: all 32-i8 quant groups first, then the
/// original f16 scale bits. Mirrors `cuda_resident::repack_q8_soa` but consumes
/// the raw GGUF wire directly (that helper expects an already-f32-scale 36B block).
#[cfg(feature = "cuda")]
fn q8_wire_to_soa(wire: &[u8]) -> Vec<u8> {
    const W: usize = 34;
    let n = wire.len() / W;
    let mut out = vec![0u8; n * 32 + n * 2];
    let (quants, scales) = out.split_at_mut(n * 32);
    for b in 0..n {
        let blk = &wire[b * W..b * W + W];
        quants[b * 32..b * 32 + 32].copy_from_slice(&blk[2..34]);
        scales[b * 2..b * 2 + 2].copy_from_slice(&blk[0..2]);
    }
    out
}

/// Quant lane of the GPU tied head: Q8_0 (`q8_gemv`, Q8_0 input), Q4_K (`q4k_gemv`,
/// Q8_K input) or Q6_K (`q6k_gemv`, Q8_K input). Each lane's GEMV reads a specific
/// GPU-side byte layout — see [`gemma4_head_upload`], which is the ONLY way the head
/// weight may reach VRAM.
#[cfg(feature = "cuda")]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum HeadLane {
    Q8_0,
    Q4K,
    Q6K,
}

/// Convert the tied head's GGUF wire bytes into the GPU layout ITS GEMV reads.
///
/// None of these kernels reads the stock wire: `q8_gemv` wants the SoA split (quants
/// then f16 scales), `q4k_gemv` wants the quant-byte swizzle that makes each aux
/// lane's four stride-8 bytes one aligned i32, and `q6k_gemv` indexes super-blocks at
/// a 224-byte PADDED stride, not the 210-byte wire stride. This mirrors
/// `cuda_resident::repack_for_lane`, which is what every OTHER resident lane in the
/// tree already routes through.
///
/// Root cause of the gemma4 Q4_0 mis-decode: the Q4_K and Q6_K arms used to
/// `clone_htod` the raw wire while only the Q8_0 arm repacked. Since a Q4_0-quantized
/// gemma4 export carries a **Q4_K** `token_embd` (the E2B Q4_0 row does), that row ran
/// `q4k_gemv` over unswizzled bytes: every logit was formed from correctly-addressed
/// but wrongly-PAIRED nibbles, so the lane emitted fluent-looking nonsense instead of
/// refusing. Measured before the fix, "Name the capital of France in one word." →
/// "passe dép oficialmenteynam shalthapp lenghtynam" on CUDA vs "Paris" on the CPU
/// runtime. The Q6_K arm had the same defect one step worse — a 210-vs-224 stride
/// mismatch that also reads past the end of the allocation.
///
/// Head lane is chosen from `token_embd`'s format, which no admission check inspects,
/// so the only gemma4 row ever validated on this lane (E4B Q8_0) was the one whose
/// head happened to be Q8_0. Routing all three lanes through one function is what
/// keeps that class of bug from coming back.
#[cfg(feature = "cuda")]
fn gemma4_head_upload(lane: HeadLane, wire: &[u8]) -> Vec<u8> {
    match lane {
        HeadLane::Q8_0 => q8_wire_to_soa(wire),
        HeadLane::Q4K => crate::cuda_resident::swz_q4k_blocks(wire),
        HeadLane::Q6K => crate::cuda_resident::pad_q6k_blocks(wire),
    }
}

/// Compact snapshot of the two routed-expert residency directories.
///
/// `intersection_records` are physically present in both page-locked host RAM
/// and the SSER VRAM arena. `union_records` counts distinct `(layer, expert)`
/// keys across both tiers, so it exposes inclusive-cache duplication directly.
#[cfg(feature = "cuda")]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct Gemma4SserHostResidency {
    pub sser_records: usize,
    pub host_records: usize,
    pub intersection_records: usize,
    pub host_only_records: usize,
    pub union_records: usize,
}

/// One speculative round's evidence, recorded so an alpha shortfall can be *attributed*
/// rather than guessed at.
///
/// `drafts[i]` is the assistant's proposal and `target[i]` is the target's own argmax at
/// the same position, both read out of the SAME verify pass — so a mismatch here is a
/// drafter disagreement, never a bookkeeping skew. `target` is one longer than `drafts`
/// because the verify batch also carries the bonus token's own row, whose argmax is the
/// token emitted when nothing is accepted.
#[cfg(feature = "cuda")]
#[derive(Clone, Debug, Default)]
pub struct Gemma4MtpRound {
    /// KV position of the round's bonus token; `drafts[i]` is proposed for `position+1+i`.
    pub position: usize,
    /// The target-chosen token the drafter was conditioned on.
    pub bonus_token: u32,
    /// Verifier width requested after schedule/fallback selection and tail
    /// truncation. This includes the current target row.
    pub requested_verify_k: usize,
    /// Rows actually returned by the target verifier for this round.
    pub verifier_k: usize,
    /// True when the remaining output budget shortened the configured width.
    pub budget_truncated: bool,
    pub drafts: Vec<u32>,
    /// Target argmax at every verified position, `1 + drafts.len()` entries.
    pub target: Vec<u32>,
    /// Length of the agreeing prefix, i.e. the extra tokens this round yielded.
    pub accepted: usize,
    /// Wall spent in the drafter (assistant forward × K).
    pub assistant_ns: u64,
    /// Wall spent in the target's batched verify pass.
    pub verify_ns: u64,
    /// VRAM expert-arena misses charged to this round's verify pass. A miss can be served
    /// by the pinned host tier, so this is a residency metric rather than a disk-read count.
    pub misses: u64,
    /// Expert records actually read from `.cghost` during this round. This equals
    /// `misses` when no host tier exists and excludes misses served from pinned RAM.
    pub storage_reads: u64,
    /// True only when this round completed through the opt-in K-wide target
    /// verifier. Harnesses use this receipt bit to reject silent scalar fallback.
    pub kwide: bool,
    /// True only when every proposal in this round completed on the resident
    /// CUDA assistant. This is independent of `kwide`: the drafter and target
    /// verifier are separately gated lanes.
    pub cuda_assistant: bool,
}

/// Accepted-draft statistics for an MTP generation. `accepted / rounds` is alpha, the
/// number of extra tokens each verify pass yielded, and it is the drafter's real quality
/// signal — output correctness is guaranteed by the target regardless.
///
/// The wall splits are recorded next to alpha because they are the two halves of the same
/// break-even question: a round only pays if `assistant + verify` beats `1 + alpha` plain
/// decode steps, and a number for one without the other cannot answer it.
#[cfg(feature = "cuda")]
#[derive(Clone, Debug, Default)]
pub struct Gemma4MtpStats {
    /// Requested drafter lane for this generation. When true, the dense CPU
    /// assistant was never constructed by the CLI/runtime path.
    pub cuda_assistant: bool,
    pub rounds: u64,
    pub drafted: u64,
    pub accepted: u64,
    /// Prompt prefill, excluded from the decode rate.
    pub prefill_ns: u64,
    pub assistant_ns: u64,
    pub verify_ns: u64,
    /// Per-round evidence, in emission order.
    pub trace: Vec<Gemma4MtpRound>,
}

#[cfg(feature = "cuda")]
impl Gemma4MtpStats {
    /// Extra tokens accepted per verify round.
    pub fn alpha(&self) -> f64 {
        if self.rounds == 0 {
            0.0
        } else {
            self.accepted as f64 / self.rounds as f64
        }
    }
    /// Fraction of proposed drafts the target agreed with.
    pub fn acceptance_rate(&self) -> f64 {
        if self.drafted == 0 {
            0.0
        } else {
            self.accepted as f64 / self.drafted as f64
        }
    }
}

#[cfg(feature = "cuda")]
fn argmax_u32(logits: &[f32]) -> u32 {
    let mut best = 0usize;
    for (i, v) in logits.iter().enumerate() {
        if *v > logits[best] {
            best = i;
        }
    }
    best as u32
}

/// One position's output from a layer-major chunk sweep.
#[cfg(feature = "cuda")]
struct ChunkRow {
    position: usize,
    logits: Vec<f32>,
    /// Post-layer hidden for this position, captured only for a verify batch. The final
    /// norm is applied by the caller, so this is the raw layer-stack output.
    hidden_state: Option<Vec<f32>>,
}

/// Compact result consumed by greedy MTP verification. The speculative gate needs
/// only the target's argmax and the post-layer hidden row; exporting the full
/// `K * vocab` logit matrix would otherwise force roughly 7 MiB through PCIe on
/// every K=7 round.
#[cfg(feature = "cuda")]
struct MtpVerifyRow {
    position: usize,
    target: u32,
    hidden_state: Option<Vec<f32>>,
}

/// Which positions of a layer-major chunk should run the vocab head.
///
/// Prefill wants the last position only — the head is ~646 MiB of Q6_K per token, so running
/// it for every prompt token would dominate. A speculative verify wants every position,
/// because each drafted token has to be checked against the target's own argmax at its own
/// position. The sweep is otherwise identical, and sharing it is what keeps a verify batch
/// cheap: a layer's expert union is loaded once and every token in the chunk hits it.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[cfg(any(feature = "cuda", test))]
enum ChunkLogits {
    LastOnly,
    /// Prefill's final-position head plus that exact row's raw post-layer hidden.
    /// The caller applies the canonical final norm before passing it to MTP.
    LastOnlyWithHidden,
    EveryPosition,
}

#[cfg(any(feature = "cuda", test))]
impl ChunkLogits {
    fn wants_logits(self, position: usize, last: usize) -> bool {
        match self {
            Self::LastOnly | Self::LastOnlyWithHidden => position == last,
            Self::EveryPosition => true,
        }
    }

    fn capture_hidden(self, position: usize, last: usize) -> bool {
        match self {
            Self::LastOnly => false,
            Self::LastOnlyWithHidden => position == last,
            Self::EveryPosition => true,
        }
    }
}

/// Resident GPU tied head. `weight` is the vocab-major projection in its lane's GPU
/// layout (always via [`gemma4_head_upload`]); input is quantized by the fused
/// rms_norm+quantize into `inq`/`ins`; `logits` is dtoh'd once per token. `blocks` is
/// blocks-per-row passed to the GEMV (`hidden/32` for Q8_0, `hidden/256` for K-quants).
#[cfg(feature = "cuda")]
struct Gemma4HeadDev {
    lane: HeadLane,
    weight: cudarc::driver::CudaSlice<u8>,
    output_norm: cudarc::driver::CudaSlice<f32>,
    logits: cudarc::driver::CudaSlice<f32>,
    inq: cudarc::driver::CudaSlice<i8>,
    ins: cudarc::driver::CudaSlice<f32>,
    blocks: usize,
    softcap: f32,
    d_sampled: cudarc::driver::CudaSlice<u32>,
}

/// Resident PLE context-projection (the `proj·h` matvec that dominated CPU prep).
/// `proj` (per_layer_model_proj, [block_count*ple_dim x hidden] f32, ~110 MB) and
/// `proj_norm` stay resident; `ti` holds this token's per_layer_token_embd row
/// (gathered+dequantized on the CPU each token — that table is too big to reside).
#[cfg(feature = "cuda")]
struct Gemma4PleCtxDev {
    proj: cudarc::driver::CudaSlice<f32>,
    proj_norm: cudarc::driver::CudaSlice<f32>,
    ti: cudarc::driver::CudaSlice<f32>,
    ple_total: usize,
    proj_scale: f32,
    embed_scale: f32,
}

/// Number of physical SSER arena slots reserved by the opt-in frequency-
/// admission experiment. Gemma 4's routed CUDA contract is top-8, so one layer
/// can stream every selected miss without evicting or publishing a hot entry.
#[cfg(any(feature = "cuda", test))]
const SSER_FREQUENCY_SCRATCH_SLOTS: usize = 8;

/// Replacement policy for the persistent SSER VRAM directory.
///
/// Lifetime LFU is deliberately separate from the older frequency-admission
/// experiment: LFU still admits every miss and therefore keeps every physical
/// arena slot available to a K-wide union. Only the victim ordering changes.
#[cfg(any(feature = "cuda", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SserCudaEvictionPolicy {
    Lru,
    Lfu,
}

#[cfg(any(feature = "cuda", test))]
fn parse_sser_cuda_eviction_policy(value: Option<&str>) -> Result<SserCudaEvictionPolicy> {
    match value {
        None | Some("lru") => Ok(SserCudaEvictionPolicy::Lru),
        Some("lfu") => Ok(SserCudaEvictionPolicy::Lfu),
        Some(other) => Err(BackendError::InvalidModelMetadata(format!(
            "CAMELID_GEMMA4_GHOST_CUDA_EVICTION must be exactly 'lru' or 'lfu'; got {other:?}"
        ))),
    }
}

/// Exact lifetime access counters for the opt-in SSER frequency-admission
/// experiment. Counts include hits, admitted misses, and non-admitted misses.
#[cfg(any(feature = "cuda", test))]
#[derive(Default)]
struct SserFrequencyAdmissionPolicy {
    access_counts: std::collections::HashMap<(u16, u16), u64>,
}

#[cfg(any(feature = "cuda", test))]
impl SserFrequencyAdmissionPolicy {
    fn record_access(&mut self, key: (u16, u16)) -> u64 {
        let count = self.access_counts.entry(key).or_default();
        *count = count
            .checked_add(1)
            .expect("SSER expert access count overflowed u64");
        *count
    }

    fn count(&self, key: (u16, u16)) -> u64 {
        self.access_counts.get(&key).copied().unwrap_or(0)
    }
}

/// Select the least-frequently used unprotected resident, breaking equal
/// lifetime counts by LRU and then by key for deterministic receipts.
#[cfg(test)]
fn sser_lfu_victim<I>(
    residents: I,
    protected_layer: u16,
    protected_experts: &[usize],
) -> Option<(u16, u16)>
where
    I: IntoIterator<Item = ((u16, u16), u64, u64)>,
{
    residents
        .into_iter()
        .filter(|(key, _, _)| {
            key.0 != protected_layer || !protected_experts.contains(&(key.1 as usize))
        })
        .min_by_key(|(key, frequency, last_used)| (*frequency, *last_used, *key))
        .map(|(key, _, _)| key)
}

#[cfg(any(feature = "cuda", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SserFrequencyDecision {
    Admit { victim: (u16, u16) },
    Stream,
}

/// Decide a full-hot-cache miss. The coldest unprotected resident wins; equal
/// frequencies are broken by the oldest recency stamp. Admission is deliberately
/// strict: an equally frequent newcomer streams instead of churning the cache.
#[cfg(any(feature = "cuda", test))]
fn sser_frequency_decision<I>(
    incoming_frequency: u64,
    residents: I,
    protected_layer: u16,
    protected_experts: &[usize],
) -> SserFrequencyDecision
where
    I: IntoIterator<Item = ((u16, u16), u64, u64)>,
{
    let victim = residents
        .into_iter()
        .filter(|(key, _, _)| {
            key.0 != protected_layer || !protected_experts.contains(&(key.1 as usize))
        })
        .min_by_key(|(key, frequency, last_used)| (*frequency, *last_used, *key));
    match victim {
        Some((key, frequency, _)) if incoming_frequency > frequency => {
            SserFrequencyDecision::Admit { victim: key }
        }
        _ => SserFrequencyDecision::Stream,
    }
}

#[cfg(any(feature = "cuda", test))]
fn sser_frequency_scratch_slot(hot_capacity: usize, scratch_ordinal: usize) -> Option<usize> {
    (scratch_ordinal < SSER_FREQUENCY_SCRATCH_SLOTS)
        .then(|| hot_capacity.checked_add(scratch_ordinal))
        .flatten()
}

/// One cached MoE expert's slot in the fixed gate/up and down GPU arenas.
/// `last_used` is the LRU recency stamp; `frequency` mirrors the exact lifetime
/// count while frequency admission or lifetime-LFU eviction is enabled (and is
/// zero otherwise).
#[cfg(feature = "cuda")]
#[derive(Clone, Copy)]
struct SserExpertDev {
    slot: usize,
    last_used: u64,
    frequency: u64,
}

/// One cacheable page-locked staging slot for a complete routed-expert record.
/// A top-k-sized ring lets positioned `.cghost` reads land directly in DMA-ready
/// memory without pinning the multi-gigabyte mapping or allocating per miss.
#[cfg(feature = "cuda")]
struct SserTransferSlot {
    record: SserPinnedSlab,
}

/// Page-locked host memory allocated with DEFAULT (cacheable) flags.
///
/// `CudaContext::alloc_pinned` hardcodes WRITE_COMBINED. On this platform's PCIe
/// link, cacheable pinned memory measured ~18% FASTER for host→device DMA (9.4 vs
/// 7.9 GB/s back to back — see the same finding at `cuda_resident.rs`'s
/// `CacheablePinned`). The routed-expert tier is read by DMA on every VRAM miss
/// and written only when a record is first admitted, so it wants the read-fast
/// flavour. The driver auto-detects the pinned pointer, so a plain slice view
/// drives the fast async DMA path with no staging copy.
#[cfg(feature = "cuda")]
struct SserPinnedSlab {
    ptr: *mut u8,
    len: usize,
    ctx: std::sync::Arc<cudarc::driver::CudaContext>,
}

// SAFETY: `ptr` is a page-locked host allocation owned solely by this struct and
// freed on drop. The resident engine is only ever entered under the
// process-global resident-cache mutex (the same discipline that lets its
// `CudaGraph` be `Send`). The QD reader transaction may write several DISJOINT
// reserved slots concurrently; it joins every reader before the owning tier can
// be accessed again, and the per-layer CUDA fence retires DMA before a source
// slot can be recycled. No two threads receive the same byte range.
#[cfg(feature = "cuda")]
unsafe impl Send for SserPinnedSlab {}

#[cfg(feature = "cuda")]
impl SserPinnedSlab {
    fn new(ctx: &std::sync::Arc<cudarc::driver::CudaContext>, len: usize) -> Result<Self> {
        ctx.bind_to_thread().map_err(cu)?;
        // flags = 0 → cacheable (NOT write-combined). max(1) avoids a zero-size alloc.
        let ptr =
            unsafe { cudarc::driver::result::malloc_host(len.max(1), 0) }.map_err(cu)? as *mut u8;
        if ptr.is_null() {
            return Err(BackendError::InvalidModelMetadata(
                "Ghost-MoE CUDA host tier: malloc_host returned null".into(),
            ));
        }
        Ok(Self {
            ptr,
            len,
            ctx: ctx.clone(),
        })
    }

    /// SAFETY contract for both accessors: `range` must lie inside `0..len`, and
    /// the caller must not alias one slot mutably while a DMA from it is in
    /// flight. The tier enforces that by never recycling a slot that the current
    /// route selected (`protected`), mirroring the VRAM arena's own invariant.
    fn slice(&self, start: usize, len: usize) -> &[u8] {
        debug_assert!(start + len <= self.len);
        unsafe { std::slice::from_raw_parts(self.ptr.add(start), len) }
    }

    fn slice_mut(&mut self, start: usize, len: usize) -> &mut [u8] {
        debug_assert!(start + len <= self.len);
        unsafe { std::slice::from_raw_parts_mut(self.ptr.add(start), len) }
    }
}

#[cfg(feature = "cuda")]
impl Drop for SserPinnedSlab {
    fn drop(&mut self) {
        let _ = self.ctx.bind_to_thread();
        // Error exits can bypass the normal copy-event dependency. Drain the
        // context before releasing a possible in-flight DMA source.
        let _ = self.ctx.synchronize();
        unsafe {
            let _ = cudarc::driver::result::free_host(self.ptr as *mut std::ffi::c_void);
        }
    }
}

/// Small cacheable page-locked row used as the CUDA-to-CPU MoE router handoff.
///
/// cudarc's `PinnedHostSlice` deliberately requests WRITE_COMBINED memory, which
/// is excellent for CPU writes but makes the router's repeated CPU reads very
/// expensive. This allocation uses CUDA host-allocation flags 0 instead, keeping
/// the row cacheable while still allowing a genuinely asynchronous DtoH.
#[cfg(feature = "cuda")]
struct RouterPinnedRow {
    ptr: *mut f32,
    len: usize,
    ctx: std::sync::Arc<cudarc::driver::CudaContext>,
}

// SAFETY: the allocation is uniquely owned and only used while the resident
// runtime is protected by its process-global mutex. GPU access is additionally
// fenced by `Gemma4CudaResident::router_copy_done` before a CPU slice is exposed.
#[cfg(feature = "cuda")]
unsafe impl Send for RouterPinnedRow {}

#[cfg(feature = "cuda")]
impl RouterPinnedRow {
    fn new(ctx: &std::sync::Arc<cudarc::driver::CudaContext>, len: usize) -> Result<Self> {
        ctx.bind_to_thread().map_err(cu)?;
        let bytes = len
            .max(1)
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| {
                BackendError::InvalidModelMetadata(
                    "Gemma 4 CUDA router row allocation size overflow".into(),
                )
            })?;
        // flags = 0 selects cacheable page-locked memory (not WRITE_COMBINED).
        let ptr = unsafe { cudarc::driver::result::malloc_host(bytes, 0) }.map_err(cu)? as *mut f32;
        if ptr.is_null() {
            return Err(BackendError::InvalidModelMetadata(
                "Gemma 4 CUDA router row malloc_host returned null".into(),
            ));
        }
        // Establish valid f32 values before this raw allocation is ever exposed
        // as a Rust slice. The first DtoH overwrites the logical `len` elements.
        unsafe { std::ptr::write_bytes(ptr, 0, len.max(1)) };
        Ok(Self {
            ptr,
            len,
            ctx: ctx.clone(),
        })
    }

    /// Mutable DMA destination. The caller must record `router_copy_done`
    /// immediately after enqueueing the DtoH and must not expose either slice
    /// accessor to CPU code until that event has synchronized.
    fn as_mut_slice(&mut self) -> &mut [f32] {
        // SAFETY: `ptr` owns at least `len * size_of::<f32>()` initialized-or-DMA-
        // writable bytes for this allocation's lifetime; `&mut self` prevents a
        // second host alias. CUDA/CPU temporal aliasing is fenced by the caller.
        unsafe { std::slice::from_raw_parts_mut(self.ptr, self.len) }
    }

    /// Cacheable CPU view. Callers synchronize `router_copy_done` first.
    fn as_slice(&self) -> &[f32] {
        // SAFETY: same allocation invariant as `as_mut_slice`; the explicit
        // copy-done fence guarantees CUDA no longer mutates these bytes.
        unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
    }
}

#[cfg(feature = "cuda")]
impl Drop for RouterPinnedRow {
    fn drop(&mut self) {
        let _ = self.ctx.bind_to_thread();
        // Error exits can bypass the normal per-layer copy-done wait. Drain the
        // context before releasing host memory so an in-flight DtoH cannot retain
        // a dangling destination pointer.
        let _ = self.ctx.synchronize();
        unsafe {
            let _ = cudarc::driver::result::free_host(self.ptr as *mut std::ffi::c_void);
        }
    }
}

/// Tier 2 of the routed-expert hierarchy: a bounded, page-locked host arena of
/// whole `.cghost` expert records, sitting between the VRAM cache and storage.
///
/// The tier exists because storage cannot serve this workload. One decode step
/// routes 240 records (806 MB on the 26B row); the VRAM cache holds ~21% of the
/// 3840 slices, so ~73 records per token have to come from somewhere else. The
/// tracked box's whole-record QD sweep reaches 1.04 GB/s at QD1, 2.42 GB/s at
/// QD4, and 3.03 GB/s at QD28. Scalar decode still declines caller-side QD4
/// because it exposes only 0.62 distinct storage reads per layer; a K-wide union
/// is the first path with enough independent misses to use that throughput.
///
/// Records are held in fixed-stride slots inside ONE page-locked slab rather than
/// as individual heap allocations, which is what makes a tier hit cost a single
/// async DMA: the copy stream reads the slot directly and the CPU never touches
/// the bytes. Staging each miss through a pinned ring instead would add a
/// ~3.19 MiB host memcpy per miss — about 0.4 ms, or ~30 ms/token at 73 misses.
/// Page-locked records are allocated in chunks of this many slots rather than as
/// one slab. Measured on the tracked box: a single 7.9 GiB `malloc_host` fails
/// with `CUDA_ERROR_OUT_OF_MEMORY` even with 9.7 GiB free, while the same total
/// in ~800 MiB pieces does not have to find one contiguous locked range. Chunking
/// also makes the tier degrade gracefully — a request the host cannot fully honour
/// keeps the chunks it did get instead of collapsing to no tier at all, which is
/// the difference between a smaller tier and falling all the way back to storage.
#[cfg(feature = "cuda")]
const GHOST_CUDA_HOST_TIER_SLOTS_PER_CHUNK: usize = 256;

#[cfg(any(feature = "cuda", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SserHostTierEvictionPolicy {
    Lru,
    Mru,
}

#[cfg(any(feature = "cuda", test))]
impl SserHostTierEvictionPolicy {
    #[cfg(feature = "cuda")]
    const fn as_str(self) -> &'static str {
        match self {
            Self::Lru => "lru",
            Self::Mru => "mru",
        }
    }

    fn select_victim(
        self,
        recency: &std::collections::BTreeSet<(u64, u16, u16)>,
        protected_layer: u16,
        protected_experts: &[usize],
    ) -> Option<(u64, u16, u16)> {
        let eligible = |(_, layer, expert): &(u64, u16, u16)| {
            *layer != protected_layer || !protected_experts.contains(&(*expert as usize))
        };
        match self {
            Self::Lru => recency.iter().copied().find(eligible),
            Self::Mru => recency.iter().rev().copied().find(eligible),
        }
    }
}

#[cfg(any(feature = "cuda", test))]
fn parse_sser_host_tier_eviction_policy(value: Option<&str>) -> Result<SserHostTierEvictionPolicy> {
    match value {
        None | Some("lru") => Ok(SserHostTierEvictionPolicy::Lru),
        Some("mru") => Ok(SserHostTierEvictionPolicy::Mru),
        Some(other) => Err(BackendError::InvalidModelMetadata(format!(
            "CAMELID_GEMMA4_GHOST_HOST_TIER_EVICTION must be exactly 'lru' or 'mru'; got {other:?}"
        ))),
    }
}

#[cfg(feature = "cuda")]
struct SserHostTier {
    /// Page-locked chunks, each holding `slots_per_chunk` whole records. A record
    /// never straddles a chunk boundary.
    chunks: Vec<SserPinnedSlab>,
    slots_per_chunk: usize,
    /// Byte stride of the largest whole expert record. Individual projection
    /// ranges remain role-aware, so layers may use different formats or tensor
    /// order without changing the slot geometry.
    stride: usize,
    entries: std::collections::HashMap<(u16, u16), SserHostEntry>,
    /// Recency index keyed by `(last_used, layer, expert)`. Unlike scanning
    /// `entries` on every miss, a recyclable endpoint is found in O(log n), plus
    /// at most the route-protected entries skipped by the selected policy.
    lru: std::collections::BTreeSet<(u64, u16, u16)>,
    eviction_policy: SserHostTierEvictionPolicy,
    free_slots: Vec<usize>,
    clock: u64,
    hits: u64,
    misses: u64,
    bytes_read: u64,
    /// `CAMELID_GEMMA4_GHOST_ARENA_SOA=1`: every record is repacked to the
    /// quants-first SoA layout AT INSERT (storage read -> tier slot), so the
    /// HtoD path DMAs the already-repacked bytes unchanged and the arenas hold
    /// exactly what the SoA kernels read. Every tier fill site must honor this.
    soa_repack: bool,
}

#[cfg(feature = "cuda")]
type SserHostTierReadyCallback<'a> =
    dyn FnMut(&SserHostTier, std::ops::Range<usize>, &[usize]) -> Result<()> + 'a;

#[cfg(feature = "cuda")]
struct SserHostEntry {
    slot: usize,
    last_used: u64,
}

/// Resident per-layer scratch for the routed MoE branch.
///
/// These were allocated per layer per token. With a 95.9%-hit route — i.e. with
/// expert transfers all but removed — the expert loop still burned 26.7 ms/token
/// in prep/alloc, which at 30 layers is 0.89 ms of driver work per layer against
/// a 50 ms/token budget. Every buffer here is sized to the per-layer maximum at
/// load, so a layer uses a prefix and the kernels read byte-identical inputs.
#[cfg(feature = "cuda")]
struct MoeScratchDev {
    /// Q8_0 scales of the shared expert input (`hidden / 32`).
    in_s: cudarc::driver::CudaSlice<f32>,
    /// Q8_0 quants of the shared expert input (`hidden`).
    in_q: cudarc::driver::CudaSlice<i8>,
    /// Fused gate‖up GEMV output, `max_route * 2 * n_ff_exp`.
    gate_up: cudarc::driver::CudaSlice<f32>,
    /// GeGLU output requantized to Q8_0, `max_route * n_ff_exp`.
    geglu_q: cudarc::driver::CudaSlice<i8>,
    /// GeGLU Q8_0 scales, `max_route * n_ff_exp / 32`.
    geglu_s: cudarc::driver::CudaSlice<f32>,
    /// Per-expert down-GEMV outputs in router order, `max_route * hidden`.
    y_all: cudarc::driver::CudaSlice<f32>,
    /// Preallocated slots buffer for routed expert execution (`max_route`).
    slots: cudarc::driver::CudaSlice<i32>,
    /// Preallocated routes buffer for routed expert execution (`max_route`).
    routes: cudarc::driver::CudaSlice<i32>,
    /// Preallocated route_scales buffer for routed expert execution (`max_route`).
    route_scales: cudarc::driver::CudaSlice<f32>,
    /// Preallocated MoE accumulator (`hidden`).
    moe_acc: cudarc::driver::CudaSlice<f32>,
    /// Reused host-side route metadata. Keeping these beside the device scratch
    /// removes five allocator round-trips from every MoE layer.
    hit_slots_host: Vec<i32>,
    hit_routes_host: Vec<i32>,
    miss_slots_host: Vec<i32>,
    miss_routes_host: Vec<i32>,
    route_scales_host: Vec<f32>,
}

/// Lazily allocated storage for the exact Gemma 4 K-wide MTP verifier.
///
/// Every tensor is token-major unless its name says otherwise. The capacity is
/// fixed at [`MAX_MTP_VERIFY_ROWS`] so the current target token plus all thirteen
/// assistant drafts can share each common/expert weight read. Routed expert
/// matrices remain assignment-major because their CSR kernels group work by the
/// union expert; `route_to_assignment` restores token/router-rank order only at
/// the final weighted sum.
#[cfg(feature = "cuda")]
struct Gemma4VerifyScratchDev {
    cap: usize,
    h: cudarc::driver::CudaSlice<f32>,
    normed: cudarc::driver::CudaSlice<f32>,
    in_q: cudarc::driver::CudaSlice<i8>,
    in_s: cudarc::driver::CudaSlice<f32>,
    in_qk: cudarc::driver::CudaSlice<i8>,
    in_sk: cudarc::driver::CudaSlice<f32>,
    q: cudarc::driver::CudaSlice<f32>,
    k: cudarc::driver::CudaSlice<f32>,
    v: cudarc::driver::CudaSlice<f32>,
    attn: cudarc::driver::CudaSlice<f32>,
    proj: cudarc::driver::CudaSlice<f32>,
    gate: cudarc::driver::CudaSlice<f32>,
    up: cudarc::driver::CudaSlice<f32>,
    geglu: cudarc::driver::CudaSlice<f32>,
    mlp: cudarc::driver::CudaSlice<f32>,
    ffn_out: cudarc::driver::CudaSlice<f32>,
    moe_acc: cudarc::driver::CudaSlice<f32>,
    /// Layer-major compact RoPE tables. `rope_offsets[li]` begins a
    /// `[cap][plan[li].head_dim/2]` region in each device allocation.
    cos: cudarc::driver::CudaSlice<f32>,
    sin: cudarc::driver::CudaSlice<f32>,
    rope_offsets: Vec<usize>,
    expert_gate_up: cudarc::driver::CudaSlice<f32>,
    expert_geglu_q: cudarc::driver::CudaSlice<i8>,
    expert_geglu_s: cudarc::driver::CudaSlice<f32>,
    expert_y: cudarc::driver::CudaSlice<f32>,
    union_slots: cudarc::driver::CudaSlice<i32>,
    token_offsets: cudarc::driver::CudaSlice<i32>,
    token_ids: cudarc::driver::CudaSlice<i32>,
    assignment_ids: cudarc::driver::CudaSlice<i32>,
    route_to_assignment: cudarc::driver::CudaSlice<i32>,
    route_scales: cudarc::driver::CudaSlice<f32>,
    logits: cudarc::driver::CudaSlice<f32>,
    /// Device-side target argmax for each verifier row. Only this compact prefix
    /// crosses PCIe; logits remain resident.
    sampled: cudarc::driver::CudaSlice<u32>,
    /// Cacheable page-locked K-row handoff for the exact CPU router.
    router_host: RouterPinnedRow,
    /// Reused host staging for the router's exact pre-norm-2 Q8_0 bytes.
    expert_q_host: Vec<i8>,
    expert_s_host: Vec<f32>,
}

/// Persistent device state for the host-fed, full-Q4 MTP assistant. The target
/// embedding for the bonus token is still gathered on the CPU, but every model
/// contraction, attention layer, recurrent projection, tied head, and argmax is
/// executed on `cap_stream`. The recurrent hidden never leaves the device.
#[cfg(feature = "cuda")]
struct Gemma4MtpCudaScratchDev {
    joined: cudarc::driver::CudaSlice<f32>,
    hidden: cudarc::driver::CudaSlice<f32>,
    normed: cudarc::driver::CudaSlice<f32>,
    q: cudarc::driver::CudaSlice<f32>,
    context: cudarc::driver::CudaSlice<f32>,
    attn: cudarc::driver::CudaSlice<f32>,
    gate: cudarc::driver::CudaSlice<f32>,
    up: cudarc::driver::CudaSlice<f32>,
    geglu: cudarc::driver::CudaSlice<f32>,
    ffn: cudarc::driver::CudaSlice<f32>,
    recurrent: cudarc::driver::CudaSlice<f32>,
    logits: cudarc::driver::CudaSlice<f32>,
    cos: cudarc::driver::CudaSlice<f32>,
    sin: cudarc::driver::CudaSlice<f32>,
    /// Full-attention rope tables get their own buffers so BOTH variants can be
    /// uploaded once per draft round (position is fixed across a round) instead
    /// of re-uploaded per layer per proposal; `cos`/`sin` hold the sliding pair.
    cos_full: cudarc::driver::CudaSlice<f32>,
    sin_full: cudarc::driver::CudaSlice<f32>,
    position: cudarc::driver::CudaSlice<i32>,
    argmax: cudarc::driver::CudaSlice<u32>,
    /// One argmax per proposal, drained in a single round-end DtoH by the
    /// device draft chain.
    draft_ring: cudarc::driver::CudaSlice<u32>,
    scores: cudarc::driver::CudaSlice<f32>,
}

